(6140),_=t(3173);let C=[{slug:"frere-jacques",kind:"poem",title:"Fr\xe8re Jacques",title_en:"Brother John",author:"Traditional",level:"A1",minutes:3,summary_en:"A classic French round about a monk who overslept the morning bells.",summary_hi:"एक पारंपरिक फ़्रेंच गीत: एक भिक्षु जो सुबह की घंटियाँ बजाना भूलकर सो गया।",source:"Public domain",passages:[{fr:"Fr\xe8re Jacques, Fr\xe8re Jacques,\nDormez-vous ? Dormez-vous ?",en:"Brother Jacques, Brother Jacques,\nAre you sleeping? Are you sleeping?"},{fr:"Sonnez les matines,\nSonnez les matines,\nDing, ding, dong.",en:"Ring the morning bells,\nRing the morning bells,\nDing, ding, dong."}],glossary:[{fr:"dormir",en:"to sleep",hi:"सोना"},{fr:"dormez-vous ?",en:"are you sleeping? (formal “vous”)",hi:"क्या आप सो रहे हैं?"},{fr:"sonner",en:"to ring",hi:"बजाना; घंटी बजाना"},{fr:"les matines",en:"morning prayers / morning bells",hi:"सुबह की प्रार्थना की घंटियाँ"}],questions:[{q:"What is the singer asking Brother Jacques?",options:["Where he lives","Whether he is sleeping","What time it is","Whether he is hungry"],correct:1,explain:"\xab Dormez-vous ? \xbb means “Are you sleeping?” — a question formed by inverting the verb and \xab vous \xbb."}]},{slug:"au-clair-de-la-lune",kind:"poem",title:"Au clair de la lune",title_en:"By the Light of the Moon",author:"Traditional",level:"A1",minutes:4,summary_en:"A beloved lullaby: Pierrot is asked to lend a pen and open his door on a dark night.",summary_hi:"एक प्रसिद्ध लोरी: अँधेरी रात में पियेरो से कलम माँगी जाती है और दरवाज़ा खोलने को कहा जाता है।",source:"Public domain",passages:[{fr:"Au clair de la lune,\nMon ami Pierrot,\nPr\xeate-moi ta plume\nPour \xe9crire un mot.",en:"By the light of the moon,\nMy friend Pierrot,\nLend me your pen\nTo write a word."},{fr:"Ma chandelle est morte,\nJe n’ai plus de feu ;\nOuvre-moi ta porte,\nPour l’amour de Dieu.",en:"My candle is dead,\nI have no more light;\nOpen your door to me,\nFor the love of God."}],glossary:[{fr:"la lune",en:"the moon",hi:"चाँद"},{fr:"pr\xeater",en:"to lend",hi:"उधार देना"},{fr:"la plume",en:"the pen (feather quill)",hi:"कलम"},{fr:"la chandelle",en:"the candle",hi:"मोमबत्ती"},{fr:"ouvrir",en:"to open",hi:"खोलना"}],questions:[{q:"What does the speaker want to borrow?",options:["A candle","A pen","A door","A book"],correct:1,explain:"\xab Pr\xeate-moi ta plume \xbb — “lend me your pen”. The imperative \xab pr\xeate \xbb + \xab moi \xbb is a command."}]},{slug:"sur-le-pont-davignon",kind:"poem",title:"Sur le pont d’Avignon",title_en:"On the Bridge of Avignon",author:"Traditional",level:"A2",minutes:3,summary_en:"A folk dance song about everyone dancing in a circle on the famous bridge in Avignon.",summary_hi:"अविन्योन के प्रसिद्ध पुल पर सबके गोल घेरे में नाचने का लोकगीत।",source:"Public domain",passages:[{fr:"Sur le pont d’Avignon,\nL’on y danse, l’on y danse,\nSur le pont d’Avignon,\nL’on y danse tous en rond.",en:"On the bridge of Avignon,\nPeople dance there, people dance there,\nOn the bridge of Avignon,\nPeople dance there, all in a circle."}],glossary:[{fr:"le pont",en:"the bridge",hi:"पुल"},{fr:"danser",en:"to dance",hi:"नाचना"},{fr:"y",en:"there (replaces “sur le pont”)",hi:"वहाँ"},{fr:"tous en rond",en:"all in a circle",hi:"सब गोल घेरे में"},{fr:"l’on",en:"one / people (literary “on”)",hi:"लोग"}],questions:[{q:"What does the pronoun \xab y \xbb stand for in \xab L’on y danse \xbb?",options:["The dance","On the bridge","Everyone","Tomorrow"],correct:1,explain:"\xab Y \xbb replaces a place already mentioned: \xab Sur le pont d’Avignon \xbb. Hence \xab on y danse \xbb = people dance there."}]},{slug:"le-corbeau-et-le-renard",kind:"poem",title:"Le Corbeau et le Renard",title_en:"The Crow and the Fox",author:"Jean de La Fontaine",year:"1668",level:"B1",minutes:6,summary_en:"The most famous fable in French: a flattering fox tricks a crow into dropping its cheese.",summary_hi:"फ़्रेंच की सबसे मशहूर कहानी-कविता: चापलूस लोमड़ी कौवे से उसका पनीर गिरवा लेती है।",source:"Public domain",passages:[{fr:"Ma\xeetre Corbeau, sur un arbre perch\xe9,\nTenait en son bec un fromage.\nMa\xeetre Renard, par l’odeur all\xe9ch\xe9,\nLui tint \xe0 peu pr\xe8s ce langage :",en:"Master Crow, perched on a tree,\nHeld a cheese in his beak.\nMaster Fox, lured by the smell,\nSpoke to him more or less in these words:"},{fr:"\xab H\xe9 ! bonjour, Monsieur du Corbeau.\nQue vous \xeates joli ! que vous me semblez beau !\nSans mentir, si votre ramage\nSe rapporte \xe0 votre plumage,\nVous \xeates le Ph\xe9nix des h\xf4tes de ces bois. \xbb",en:"“Well, hello, Mister Crow.\nHow handsome you are! How fine you seem to me!\nHonestly, if your song\nMatches your plumage,\nYou are the Phoenix of all the dwellers of these woods.”"},{fr:"\xc0 ces mots le Corbeau ne se sent pas de joie ;\nEt pour montrer sa belle voix,\nIl ouvre un large bec, laisse tomber sa proie.",en:"At these words the Crow is beside himself with joy;\nAnd to show off his beautiful voice,\nHe opens a wide beak and drops his prey."},{fr:"Le Renard s’en saisit, et dit : \xab Mon bon Monsieur,\nApprenez que tout flatteur\nVit aux d\xe9pens de celui qui l’\xe9coute :\nCette le\xe7on vaut bien un fromage, sans doute. \xbb",en:"The Fox seizes it and says: “My good sir,\nLearn that every flatterer\nLives at the expense of the one who listens:\nThis lesson is surely worth a cheese.”"},{fr:"Le Corbeau, honteux et confus,\nJura, mais un peu tard, qu’on ne l’y prendrait plus.",en:"The Crow, ashamed and embarrassed,\nSwore, though a little late, that he would not be caught again."}],glossary:[{fr:"perch\xe9",en:"perched",hi:"बैठा हुआ (ऊँचाई पर)"},{fr:"le bec",en:"beak",hi:"चोंच"},{fr:"all\xe9ch\xe9",en:"tempted, lured",hi:"लालच में आया हुआ"},{fr:"le ramage",en:"birdsong",hi:"पक्षी का गान"},{fr:"le plumage",en:"plumage, feathers",hi:"पंख"},{fr:"le flatteur",en:"flatterer",hi:"चापलूस"},{fr:"aux d\xe9pens de",en:"at the expense of",hi:"की कीमत पर"},{fr:"honteux",en:"ashamed",hi:"शर्मिंदा"}],questions:[{q:"What is the moral of the fable?",options:["Never trust a fox","Flatterers live at the expense of those who listen to them","Birds should not sing","Cheese is expensive"],correct:1,explain:"The fox says it outright: \xab tout flatteur vit aux d\xe9pens de celui qui l’\xe9coute \xbb."},{q:"Why does the crow drop the cheese?",options:["It is too heavy","He opens his beak to sing","The fox pushes him","He is not hungry"],correct:1,explain:"To show off his \xab belle voix \xbb he opens a wide beak, and the cheese falls."}]},{slug:"demain-des-laube",kind:"poem",title:"Demain, d\xe8s l’aube…",title_en:"Tomorrow, at Dawn…",author:"Victor Hugo",year:"1856",level:"B1",minutes:6,summary_en:"A father walks toward his daughter’s grave. A restrained, devastating poem about grief.",summary_hi:"एक पिता अपनी बेटी की कब्र की ओर पैदल जाता है, शोक पर लिखी एक संयत और मार्मिक कविता।",source:"Public domain",passages:[{fr:"Demain, d\xe8s l’aube, \xe0 l’heure o\xf9 blanchit la campagne,\nJe partirai. Vois-tu, je sais que tu m’attends.\nJ’irai par la for\xeat, j’irai par la montagne.\nJe ne puis demeurer loin de toi plus longtemps.",en:"Tomorrow, at dawn, when the countryside turns white,\nI will set out. You see, I know you are waiting for me.\nI will go through the forest, I will go over the mountain.\nI cannot stay far from you any longer."},{fr:"Je marcherai les yeux fix\xe9s sur mes pens\xe9es,\nSans rien voir au dehors, sans entendre aucun bruit,\nSeul, inconnu, le dos courb\xe9, les mains crois\xe9es,\nTriste, et le jour pour moi sera comme la nuit.",en:"I will walk with my eyes fixed on my thoughts,\nSeeing nothing outside, hearing no sound,\nAlone, unknown, back bent, hands crossed,\nSad, and the day will be like night to me."},{fr:"Je ne regarderai ni l’or du soir qui tombe,\nNi les voiles au loin descendant vers Harfleur,\nEt quand j’arriverai, je mettrai sur ta tombe\nUn bouquet de houx vert et de bruy\xe8re en fleur.",en:"I will look at neither the gold of the falling evening,\nNor the distant sails heading down toward Harfleur,\nAnd when I arrive, I will lay on your grave\nA bouquet of green holly and flowering heather."}],glossary:[{fr:"l’aube",en:"dawn",hi:"भोर"},{fr:"blanchir",en:"to turn white",hi:"सफ़ेद होना"},{fr:"je ne puis",en:"I cannot (literary form of “je ne peux pas”)",hi:"मैं नहीं कर सकता"},{fr:"demeurer",en:"to remain, to stay",hi:"ठहरना; रहना"},{fr:"courb\xe9",en:"bent",hi:"झुका हुआ"},{fr:"la tombe",en:"grave",hi:"कब्र"},{fr:"le houx",en:"holly",hi:"हॉली (एक कंटीली झाड़ी)"}],questions:[{q:"Which tense dominates the poem?",options:["Pass\xe9 compos\xe9","Imparfait","Futur simple","Subjonctif"],correct:2,explain:"\xab Je partirai \xbb, \xab j’irai \xbb, \xab je marcherai \xbb, \xab je mettrai \xbb — all futur simple, expressing firm resolve."},{q:"Where is the speaker going?",options:["To a festival","To a loved one’s grave","To the sea","To his home"],correct:1,explain:"The last line reveals it: he will lay flowers \xab sur ta tombe \xbb."}]},{slug:"chanson-dautomne",kind:"poem",title:"Chanson d’automne",title_en:"Autumn Song",author:"Paul Verlaine",year:"1866",level:"B2",minutes:6,summary_en:"Three short stanzas where the sound of violins mirrors the speaker’s melancholy. A masterpiece of musicality.",summary_hi:"तीन छोटे छंद जिनमें वायलिन की ध्वनि कवि की उदासी का प्रतिबिंब बन जाती है: संगीतात्मकता की मिसाल।",source:"Public domain",passages:[{fr:"Les sanglots longs\nDes violons\nDe l’automne\nBlessent mon cœur\nD’une langueur\nMonotone.",en:"The long sobs\nOf the violins\nOf autumn\nWound my heart\nWith a monotonous\nLanguor."},{fr:"Tout suffocant\nEt bl\xeame, quand\nSonne l’heure,\nJe me souviens\nDes jours anciens\nEt je pleure ;",en:"All choking\nAnd pale, when\nThe hour strikes,\nI remember\nThe days of old\nAnd I weep;"},{fr:"Et je m’en vais\nAu vent mauvais\nQui m’emporte\nDe\xe7\xe0, del\xe0,\nPareil \xe0 la\nFeuille morte.",en:"And I go off\nOn the ill wind\nThat carries me\nHither and thither,\nLike the\nDead leaf."}],glossary:[{fr:"le sanglot",en:"sob",hi:"सिसकी"},{fr:"blesser",en:"to wound",hi:"घायल करना"},{fr:"la langueur",en:"languor, listlessness",hi:"सुस्ती; उदासी"},{fr:"bl\xeame",en:"pale",hi:"पीला; फीका"},{fr:"de\xe7\xe0, del\xe0",en:"here and there",hi:"इधर-उधर"},{fr:"pareil \xe0",en:"similar to, like",hi:"के समान"}],questions:[{q:"What literary device is most striking in the poem?",options:["Long prose sentences","Musicality: rhyme, short lines and repeated sounds","Dialogue","Free verse without rhyme"],correct:1,explain:"Verlaine uses very short lines and recurring sounds (l, s, on) so that the poem itself sounds like a violin."},{q:"What does the speaker compare himself to in the last stanza?",options:["A violin","A dead leaf in the wind","A pale moon","A wounded bird"],correct:1,explain:"\xab Pareil \xe0 la feuille morte \xbb — carried aimlessly by the wind."}]},{slug:"mignonne-allons-voir-si-la-rose",kind:"poem",title:"Mignonne, allons voir si la rose",title_en:"Darling, Let Us Go and See the Rose",author:"Pierre de Ronsard",year:"1553",level:"B2",minutes:5,summary_en:"A Renaissance classic on carpe diem: the rose fades quickly, so enjoy youth while it lasts.",summary_hi:"पुनर्जागरण की कालजयी कविता: गुलाब जल्दी मुरझा जाता है, इसलिए जवानी का आनंद अभी लो।",source:"Public domain",passages:[{fr:"Mignonne, allons voir si la rose\nQui ce matin avait d\xe9close\nSa robe de pourpre au soleil,\nA point perdu cette v\xeapr\xe9e\nLes plis de sa robe pourpr\xe9e,\nEt son teint au v\xf4tre pareil.",en:"Darling, let us go and see if the rose\nThat this morning had unfolded\nHer crimson gown to the sun\nHas not lost, this evening,\nThe folds of her crimson gown,\nAnd her complexion so like yours."}],glossary:[{fr:"mignonne",en:"darling (old, affectionate)",hi:"प्यारी"},{fr:"d\xe9clore",en:"to open (archaic)",hi:"खोलना (पुराना शब्द)"},{fr:"la pourpre",en:"crimson",hi:"गहरा लाल"},{fr:"a point perdu",en:"has not lost (archaic “point” = “pas”)",hi:"खोया नहीं है"},{fr:"cette v\xeapr\xe9e",en:"this evening (archaic)",hi:"आज शाम"},{fr:"le teint",en:"complexion",hi:"रंगत"}],questions:[{q:"The rose is a symbol of…",options:["The garden","The fleeting nature of youth and beauty","The poet’s house","The sunrise"],correct:1,explain:"Ronsard compares the rose’s short life to the beloved’s youth: the Latin theme of carpe diem."}]},{slug:"le-pont-mirabeau",kind:"poem",title:"Le Pont Mirabeau",title_en:"The Mirabeau Bridge",author:"Guillaume Apollinaire",year:"1912",level:"B2",minutes:5,summary_en:"A modern poem without punctuation: time flows away like the Seine, but the poet remains.",summary_hi:"बिना विराम-चिह्नों वाली आधुनिक कविता: समय सीन नदी की तरह बह जाता है, पर कवि ठहरा रहता है।",source:"Public domain",passages:[{fr:"Sous le pont Mirabeau coule la Seine\nEt nos amours\nFaut-il qu’il m’en souvienne\nLa joie venait toujours apr\xe8s la peine",en:"Under the Mirabeau bridge flows the Seine\nAnd our loves\nMust I remember them\nJoy always came after sorrow"},{fr:"Vienne la nuit sonne l’heure\nLes jours s’en vont je demeure",en:"Let night come, let the hour strike\nThe days go by, I remain"}],glossary:[{fr:"couler",en:"to flow",hi:"बहना"},{fr:"faut-il que + subjonctif",en:"must it be that…",hi:"क्या ज़रूरी है कि…"},{fr:"la peine",en:"sorrow, pain",hi:"दुख; पीड़ा"},{fr:"vienne la nuit",en:"let night come (subjunctive of wish)",hi:"रात आ जाए"},{fr:"je demeure",en:"I remain",hi:"मैं ठहरा रहता हूँ"}],questions:[{q:"What is unusual about the form of the original poem?",options:["It has no punctuation","It is written in English","It has no verbs","It is a single word"],correct:0,explain:"Apollinaire removed the punctuation, letting the lines flow into one another like the river."},{q:"\xab Vienne la nuit \xbb uses which mood?",options:["Indicatif","Subjonctif (a wish or command)","Conditionnel","Imp\xe9ratif"],correct:1,explain:"An inverted subjunctive expressing a wish: “let the night come”."}]},{slug:"le-dormeur-du-val",kind:"poem",title:"Le Dormeur du val",title_en:"The Sleeper in the Valley",author:"Arthur Rimbaud",year:"1870",level:"B2",minutes:6,summary_en:"A sunlit valley and a young soldier who seems to be sleeping. The last line changes everything. (Excerpt)",summary_hi:"धूप से भरी घाटी और एक नौजवान सिपाही जो सोया लगता है। आख़िरी पंक्ति सब बदल देती है। (अंश)",source:"Public domain",passages:[{fr:"C’est un trou de verdure o\xf9 chante une rivi\xe8re\nAccrochant follement aux herbes des haillons\nD’argent ; o\xf9 le soleil, de la montagne fi\xe8re,\nLuit : c’est un petit val qui mousse de rayons.",en:"It is a hollow of greenery where a river sings,\nMadly catching on the grasses shreds\nOf silver; where the sun, from the proud mountain,\nShines: it is a small valley frothing with rays."},{fr:"Les parfums ne font pas frissonner sa narine ;\nIl dort dans le soleil, la main sur sa poitrine,\nTranquille. Il a deux trous rouges au c\xf4t\xe9 droit.",en:"Perfumes do not make his nostril quiver;\nHe sleeps in the sun, his hand on his chest,\nPeaceful. He has two red holes in his right side."}],glossary:[{fr:"le val",en:"valley (literary)",hi:"घाटी"},{fr:"accrocher",en:"to catch, to hang on",hi:"अटकाना"},{fr:"les haillons",en:"rags, tatters",hi:"चिथड़े"},{fr:"luire",en:"to gleam",hi:"चमकना"},{fr:"frissonner",en:"to shiver, quiver",hi:"सिहरना"},{fr:"la narine",en:"nostril",hi:"नथुना"}],questions:[{q:"What does the final line reveal?",options:["The soldier is dreaming","The soldier is dead","The soldier is hungry","The soldier is lost"],correct:1,explain:"\xab Deux trous rouges au c\xf4t\xe9 droit \xbb are bullet wounds. The peaceful scene hides a war death."}]},{slug:"heureux-qui-comme-ulysse",kind:"poem",title:"Heureux qui, comme Ulysse…",title_en:"Happy Is He Who, Like Ulysses…",author:"Joachim du Bellay",year:"1558",level:"C1",minutes:7,summary_en:"A Renaissance sonnet written in Rome by a poet who misses his modest village in France. (Opening)",summary_hi:"रोम में लिखा गया पुनर्जागरण का सॉनेट: एक कवि जो फ़्रांस के अपने साधारण गाँव को याद करता है। (आरंभ)",source:"Public domain",passages:[{fr:"Heureux qui, comme Ulysse, a fait un beau voyage,\nOu comme cestuy-l\xe0 qui conquit la toison,\nEt puis est retourn\xe9, plein d’usage et raison,\nVivre entre ses parents le reste de son \xe2ge !",en:"Happy is he who, like Ulysses, has made a fine voyage,\nOr like the one who won the Golden Fleece,\nAnd then came home, full of experience and wisdom,\nTo live among his kin for the rest of his days!"},{fr:"Quand reverrai-je, h\xe9las, de mon petit village\nFumer la chemin\xe9e, et en quelle saison\nReverrai-je le clos de ma pauvre maison,\nQui m’est une province, et beaucoup davantage ?",en:"When shall I see again, alas, from my little village\nThe chimney smoke, and in what season\nShall I see again the walled garden of my poor house,\nWhich is a province to me, and much more?"}],glossary:[{fr:"la toison (d’or)",en:"the (Golden) Fleece",hi:"सुनहरी ऊन"},{fr:"cestuy-l\xe0",en:"that one (archaic “celui-l\xe0”)",hi:"वह वाला (पुराना रूप)"},{fr:"l’usage",en:"experience",hi:"अनुभव"},{fr:"l’\xe2ge",en:"(here) lifetime",hi:"जीवन-काल"},{fr:"le clos",en:"enclosed garden / plot",hi:"घिरा हुआ बगीचा"},{fr:"davantage",en:"much more",hi:"कहीं अधिक"}],questions:[{q:"What feeling drives the poem?",options:["Anger at Rome","Nostalgia for home","Hunger","Pride in conquest"],correct:1,explain:"The poet, far away in Rome, longs for his small village and humble house: the theme of nostalgia (\xab le mal du pays \xbb)."}]},{slug:"linvitation-au-voyage",kind:"poem",title:"L’Invitation au voyage",title_en:"Invitation to the Voyage",author:"Charles Baudelaire",year:"1857",level:"C1",minutes:6,summary_en:"An invitation to an ideal land where everything is order, calm and sensual pleasure. (Excerpt)",summary_hi:"एक आदर्श देश का निमंत्रण जहाँ सब कुछ व्यवस्था, शांति और आनंद है। (अंश)",source:"Public domain",passages:[{fr:"Mon enfant, ma sœur,\nSonge \xe0 la douceur\nD’aller l\xe0-bas vivre ensemble !\nAimer \xe0 loisir,\nAimer et mourir\nAu pays qui te ressemble !",en:"My child, my sister,\nThink of the sweetness\nOf going there to live together!\nTo love at leisure,\nTo love and to die\nIn the land that resembles you!"},{fr:"L\xe0, tout n’est qu’ordre et beaut\xe9,\nLuxe, calme et volupt\xe9.",en:"There, all is but order and beauty,\nLuxury, calm and sensual delight."}],glossary:[{fr:"songer \xe0",en:"to dream of, think of",hi:"के बारे में सोचना; सपना देखना"},{fr:"la douceur",en:"sweetness, gentleness",hi:"कोमलता; मिठास"},{fr:"\xe0 loisir",en:"at leisure",hi:"फ़ुरसत से"},{fr:"ressembler \xe0",en:"to resemble",hi:"से मिलना-जुलना"},{fr:"la volupt\xe9",en:"sensual pleasure",hi:"इंद्रिय-सुख"},{fr:"ne… que",en:"only (restrictive)",hi:"केवल"}],questions:[{q:"\xab L\xe0, tout n’est qu’ordre et beaut\xe9 \xbb — what does \xab ne… que \xbb express here?",options:["A negation","Exclusivity: nothing but order and beauty","A question","A past event"],correct:1,explain:"\xab Ne… que \xbb means “only / nothing but”. Despite \xab ne \xbb, it is not a negation."}]},{slug:"le-lac",kind:"poem",title:"Le Lac",title_en:"The Lake",author:"Alphonse de Lamartine",year:"1820",level:"C1",minutes:6,summary_en:"A Romantic meditation on time that flows without return. (Opening stanza)",summary_hi:"समय पर रोमांटिक चिंतन जो कभी लौटकर नहीं आता। (आरंभिक छंद)",source:"Public domain",passages:[{fr:"Ainsi, toujours pouss\xe9s vers de nouveaux rivages,\nDans la nuit \xe9ternelle emport\xe9s sans retour,\nNe pourrons-nous jamais sur l’oc\xe9an des \xe2ges\nJeter l’ancre un seul jour ?",en:"Thus, ever driven toward new shores,\nCarried without return into eternal night,\nWill we never be able, on the ocean of the ages,\nTo cast anchor for a single day?"}],glossary:[{fr:"pousser",en:"to push, to drive",hi:"धकेलना"},{fr:"le rivage",en:"shore",hi:"किनारा"},{fr:"emport\xe9",en:"carried away",hi:"बहा ले जाया गया"},{fr:"sans retour",en:"with no return",hi:"बिना लौटे"},{fr:"jeter l’ancre",en:"to drop anchor",hi:"लंगर डालना"}],questions:[{q:"What is the central metaphor of the stanza?",options:["Life as a sea voyage","Life as a mountain","Life as a market","Life as a book"],correct:0,explain:"Time is an ocean, humans are ships driven toward new shores; the anchor stands for the wish to stop time."}]}],N=[{slug:"au-cafe",kind:"story",title:"Au caf\xe9",title_en:"At the Caf\xe9",author:"Acad\xe9mie (original)",level:"A1",minutes:4,summary_en:"L\xe9a orders a coffee and a croissant in a Paris caf\xe9. Perfect for learning ordering phrases and numbers.",summary_hi:"लेआ पेरिस के एक कैफ़े में कॉफ़ी और क्रुआसाँ मँगवाती है। ऑर्डर और संख्याओं के वाक्य सीखने के लिए बढ़िया।",source:"Original",passages:[{fr:"Il est neuf heures. L\xe9a entre dans un caf\xe9 \xe0 Paris. Elle est contente.",en:"It is nine o’clock. L\xe9a enters a caf\xe9 in Paris. She is happy."},{fr:"— Bonjour, madame. Vous d\xe9sirez ?\n— Bonjour. Un caf\xe9 et un croissant, s’il vous pla\xeet.",en:"“Hello, madam. What would you like?”\n“Hello. A coffee and a croissant, please.”"},{fr:"— Voil\xe0. \xc7a fait quatre euros cinquante.\n— Voici cinq euros. Gardez la monnaie !\n— Merci beaucoup. Bonne journ\xe9e !",en:"“Here you are. That comes to four euros fifty.”\n“Here are five euros. Keep the change!”\n“Thank you very much. Have a nice day!”"},{fr:"L\xe9a mange son croissant. Elle regarde les gens dans la rue. Elle aime Paris.",en:"L\xe9a eats her croissant. She watches the people in the street. She loves Paris."}],glossary:[{fr:"Vous d\xe9sirez ?",en:"What would you like? (waiter)",hi:"आप क्या लेंगे?"},{fr:"Voil\xe0",en:"Here you are / there you go",hi:"यह लीजिए"},{fr:"\xc7a fait…",en:"That comes to… (price)",hi:"कुल… हुआ"},{fr:"la monnaie",en:"change (coins)",hi:"खुले पैसे; रेज़गारी"},{fr:"Gardez",en:"Keep (imperative, formal)",hi:"रख लीजिए"}],questions:[{q:"How much does L\xe9a have to pay?",options:["4,00 €","4,50 €","5,00 €","5,50 €"],correct:1,explain:"\xab Quatre euros cinquante \xbb = 4,50 €. She gives 5 €."},{q:"What does \xab Gardez la monnaie \xbb mean?",options:["Count your money","Keep the change","Give me more money","Close the register"],correct:1,explain:"\xab Garder \xbb = to keep; \xab la monnaie \xbb = the change."}]},{slug:"ma-famille",kind:"story",title:"Ma famille",title_en:"My Family",author:"Acad\xe9mie (original)",level:"A1",minutes:4,summary_en:"Marc introduces his family, age, home and hobbies using \xeatre, avoir and basic adjectives.",summary_hi:"मार्क अपना परिवार, उम्र, घर और शौक बताता है। होना, रखना और आसान विशेषणों का अभ्यास।",source:"Original",passages:[{fr:"Je m’appelle Marc. J’ai vingt-cinq ans. J’habite \xe0 Lyon avec ma sœur, Claire.",en:"My name is Marc. I am twenty-five years old. I live in Lyon with my sister, Claire."},{fr:"Ma sœur a vingt-deux ans. Elle est \xe9tudiante. Elle aime la musique et elle joue du piano.",en:"My sister is twenty-two. She is a student. She likes music and she plays the piano."},{fr:"Mes parents habitent \xe0 Marseille. Mon p\xe8re est professeur et ma m\xe8re est m\xe9decin. Ils ont un petit chien blanc.",en:"My parents live in Marseille. My father is a teacher and my mother is a doctor. They have a small white dog."},{fr:"Le dimanche, nous mangeons ensemble chez mes parents. C’est un moment tr\xe8s agr\xe9able !",en:"On Sundays, we eat together at my parents’ house. It is a very pleasant time!"}],glossary:[{fr:"J’ai vingt-cinq ans",en:"I am 25 (French uses avoir for age)",hi:"मैं 25 साल का हूँ"},{fr:"jouer du piano",en:"to play the piano (jouer de + instrument)",hi:"पियानो बजाना"},{fr:"un moment agr\xe9able",en:"a pleasant time",hi:"सुखद समय"},{fr:"ensemble",en:"together",hi:"साथ में"},{fr:"chez mes parents",en:"at my parents’ place",hi:"मेरे माता-पिता के घर"}],questions:[{q:"How do you say your age in French?",options:["Je suis vingt-cinq ans","J’ai vingt-cinq ans","Je fais vingt-cinq ans","Je vais vingt-cinq ans"],correct:1,explain:"French uses \xab avoir \xbb for age: \xab J’ai vingt-cinq ans \xbb (literally “I have 25 years”)."}]},{slug:"un-week-end-a-lyon",kind:"story",title:"Un week-end \xe0 Lyon",title_en:"A Weekend in Lyon",author:"Acad\xe9mie (original)",level:"A2",minutes:5,summary_en:"A first story in the pass\xe9 compos\xe9: travel, food and sightseeing in Lyon.",summary_hi:"पासे कंपोज़े में पहली कहानी: ल्यों में यात्रा, खाना और घूमना।",source:"Original",passages:[{fr:"Samedi matin, nous avons pris le train pour Lyon. Le voyage a dur\xe9 deux heures et nous avons beaucoup parl\xe9.",en:"On Saturday morning, we took the train to Lyon. The journey lasted two hours and we talked a lot."},{fr:"\xc0 midi, nous avons d\xe9jeun\xe9 dans un petit bouchon lyonnais. J’ai mang\xe9 une quenelle et ma sœur a choisi une salade de lentilles.",en:"At noon, we had lunch in a small Lyon “bouchon” restaurant. I ate a quenelle and my sister chose a lentil salad."},{fr:"L’apr\xe8s-midi, nous sommes mont\xe9s \xe0 la basilique de Fourvi\xe8re. De l\xe0-haut, nous avons vu toute la ville, le Rh\xf4ne et la Sa\xf4ne.",en:"In the afternoon, we went up to the Fourvi\xe8re basilica. From up there, we saw the whole city, the Rh\xf4ne and the Sa\xf4ne."},{fr:"Dimanche, nous sommes rentr\xe9s fatigu\xe9s mais tr\xe8s heureux. Je n’ai pas oubli\xe9 ce week-end !",en:"On Sunday, we came home tired but very happy. I have not forgotten this weekend!"}],glossary:[{fr:"nous avons pris",en:"we took (prendre, pass\xe9 compos\xe9)",hi:"हमने लिया"},{fr:"nous sommes mont\xe9s",en:"we went up (\xeatre auxiliary, agrees)",hi:"हम ऊपर गए"},{fr:"durer",en:"to last",hi:"चलना (समय तक)"},{fr:"un bouchon lyonnais",en:"traditional Lyon bistro",hi:"ल्यों का पारंपरिक रेस्तराँ"},{fr:"rentrer",en:"to go home / return",hi:"घर लौटना"}],questions:[{q:"Why is it \xab nous sommes mont\xe9s \xbb (not \xab avons mont\xe9s \xbb)?",options:["It is a typo","Verbs of movement like monter use \xeatre in the pass\xe9 compos\xe9","Because nous is plural","Because it is Saturday"],correct:1,explain:"Verbs of motion such as aller, venir, monter, rentrer take \xab \xeatre \xbb, and the participle agrees with the subject."}]},{slug:"le-petit-chaperon-rouge-adapte",kind:"story",title:"Le Petit Chaperon rouge (adapt\xe9)",title_en:"Little Red Riding Hood (adapted)",author:"After Charles Perrault",level:"A2",minutes:5,summary_en:"A simplified retelling of the famous tale with present tense and pass\xe9 compos\xe9.",summary_hi:"प्रसिद्ध कहानी का सरल रूप, वर्तमान काल और पासे कंपोज़े में।",source:"Original",passages:[{fr:"Il \xe9tait une fois une petite fille. Elle porte toujours un manteau rouge. Alors tout le monde l’appelle \xab le Petit Chaperon rouge \xbb.",en:"Once upon a time there was a little girl. She always wears a red coat. So everyone calls her “Little Red Riding Hood”."},{fr:"Un matin, sa m\xe8re lui dit : \xab Ta grand-m\xe8re est malade. Porte-lui ce g\xe2teau et ce pot de beurre. Mais ne parle pas aux inconnus ! \xbb",en:"One morning, her mother says to her: “Your grandmother is ill. Take her this cake and this pot of butter. But do not talk to strangers!”"},{fr:"Dans la for\xeat, elle rencontre un loup. Il demande : \xab O\xf9 vas-tu, petite ? \xbb Elle r\xe9pond : \xab Chez ma grand-m\xe8re. \xbb Le loup court tr\xe8s vite et arrive avant elle.",en:"In the forest, she meets a wolf. He asks: “Where are you going, little one?” She answers: “To my grandmother’s.” The wolf runs very fast and arrives before her."},{fr:"Heureusement, un chasseur a entendu des cris. Il est entr\xe9 dans la maison et il a sauv\xe9 la grand-m\xe8re et la petite fille.",en:"Fortunately, a hunter heard some cries. He went into the house and saved the grandmother and the little girl."}],glossary:[{fr:"il \xe9tait une fois",en:"once upon a time",hi:"एक समय की बात है"},{fr:"un inconnu",en:"a stranger",hi:"अजनबी"},{fr:"un loup",en:"a wolf",hi:"भेड़िया"},{fr:"heureusement",en:"fortunately",hi:"सौभाग्य से"},{fr:"un chasseur",en:"a hunter",hi:"शिकारी"},{fr:"porte-lui",en:"take (to) her (imperative + pronoun)",hi:"उसे ले जाओ"}],questions:[{q:"What does the mother forbid?",options:["Picking flowers","Talking to strangers","Going to school","Eating the cake"],correct:1,explain:"\xab Ne parle pas aux inconnus \xbb — a negative imperative: ne + verb + pas."}]},{slug:"une-lettre-a-ma-grand-mere",kind:"story",title:"Une lettre \xe0 ma grand-m\xe8re",title_en:"A Letter to My Grandmother",author:"Acad\xe9mie (original)",level:"B1",minutes:6,summary_en:"A personal letter mixing imparfait, pass\xe9 compos\xe9 and futur: memories, news and plans.",summary_hi:"एक निजी पत्र जिसमें इम्पार्फ़े, पासे कंपोज़े और भविष्य काल मिले हुए हैं: यादें, ख़बरें और योजनाएँ।",source:"Original",passages:[{fr:"Ch\xe8re Mamie,\n\nJ’esp\xe8re que tu vas bien. Hier, en rangeant ma chambre, j’ai retrouv\xe9 la photo de ta maison en Bretagne. Quand j’\xe9tais petit, nous y passions tous nos \xe9t\xe9s.",en:"Dear Granny,\n\nI hope you are well. Yesterday, while tidying my room, I found the photo of your house in Brittany again. When I was little, we spent every summer there."},{fr:"Je me souviens du bruit de la mer le matin et de l’odeur de ton pain perdu. \xc0 cette \xe9poque, je pensais que le temps ne passerait jamais.",en:"I remember the sound of the sea in the morning and the smell of your French toast. At that time, I thought time would never pass."},{fr:"Depuis, beaucoup de choses ont chang\xe9. J’ai fini mes \xe9tudes et j’ai trouv\xe9 un travail \xe0 Toulouse. Je ne sais pas encore si je resterai l\xe0-bas longtemps.",en:"Since then, many things have changed. I have finished my studies and found a job in Toulouse. I do not yet know if I will stay there long."},{fr:"Si tout va bien, je viendrai te voir en juillet. Nous irons au march\xe9 ensemble, et tu me raconteras encore tes histoires.\n\nJe t’embrasse tr\xe8s fort,\nMarc",en:"If all goes well, I will come to see you in July. We will go to the market together, and you will tell me your stories again.\n\nSending you a big hug,\nMarc"}],glossary:[{fr:"en rangeant",en:"while tidying (g\xe9rondif)",hi:"सँभालते/सजाते हुए"},{fr:"retrouver",en:"to find again",hi:"फिर से पाना"},{fr:"je me souviens de",en:"I remember",hi:"मुझे याद है"},{fr:"le pain perdu",en:"French toast",hi:"फ़्रेंच टोस्ट"},{fr:"Si tout va bien, je viendrai",en:"if + pr\xe9sent, futur (real condition)",hi:"यदि सब ठीक रहा, तो मैं आऊँगा"},{fr:"Je t’embrasse",en:"Love, / hugs (closing a letter)",hi:"ढेर सारा प्यार"}],questions:[{q:"Which tense describes the childhood memories (\xab nous y passions tous nos \xe9t\xe9s \xbb)?",options:["Pass\xe9 compos\xe9","Imparfait","Futur simple","Plus-que-parfait"],correct:1,explain:"Habits and background in the past use the imparfait: passions, pensais, \xe9tais."},{q:"\xab Si tout va bien, je viendrai \xbb follows which pattern?",options:["si + imparfait → conditionnel","si + pr\xe9sent → futur","si + pass\xe9 compos\xe9 → pr\xe9sent","si + futur → futur"],correct:1,explain:"A real, possible condition: si + pr\xe9sent, futur simple."}]},{slug:"le-petit-chaperon-rouge-perrault",kind:"story",title:"Le Petit Chaperon rouge",title_en:"Little Red Riding Hood",author:"Charles Perrault",year:"1697",level:"B2",minutes:6,summary_en:"The opening of Perrault’s original tale, with its classical vocabulary and imperfect subjunctive. (Opening)",summary_hi:"पेरो की मूल कहानी का आरंभ, उसकी शास्त्रीय शब्दावली और इम्पार्फ़े सब्जंक्टिव के साथ। (आरंभ)",source:"Public domain",passages:[{fr:"Il \xe9tait une fois une petite fille de village, la plus jolie qu’on e\xfbt su voir ; sa m\xe8re en \xe9tait folle, et sa m\xe8re-grand plus folle encore.",en:"Once upon a time there was a little village girl, the prettiest anyone could have seen; her mother was mad about her, and her grandmother even more so."},{fr:"Cette bonne femme lui fit faire un petit chaperon rouge, qui lui seyait si bien que partout on l’appelait le Petit Chaperon rouge.",en:"This good woman had a little red hood made for her, which suited her so well that everywhere she was called Little Red Riding Hood."}],glossary:[{fr:"qu’on e\xfbt su voir",en:"that one could have seen (plus-que-parfait du subjonctif, literary)",hi:"जितनी कोई देख सका हो (साहित्यिक रूप)"},{fr:"sa m\xe8re-grand",en:"her grandmother (archaic)",hi:"उसकी दादी/नानी (पुराना शब्द)"},{fr:"fou / folle de",en:"crazy about, doting on",hi:"पर फ़िदा; दीवाना"},{fr:"le chaperon",en:"hood",hi:"टोपी जैसा हुड"},{fr:"seoir (lui seyait)",en:"to suit (literary)",hi:"फबना; शोभा देना"},{fr:"lui fit faire",en:"had (something) made for her (faire faire)",hi:"उसके लिए बनवाया"}],questions:[{q:"\xab La plus jolie qu’on e\xfbt su voir \xbb uses…",options:["The present subjunctive","A literary past subjunctive after a superlative","The conditional","The imperative"],correct:1,explain:"After a superlative, French can use the subjunctive. \xab E\xfbt su \xbb is the formal literary past form."}]},{slug:"candide-ouverture",kind:"story",title:"Candide, chapitre premier",title_en:"Candide, Chapter One",author:"Voltaire",year:"1759",level:"B2",minutes:6,summary_en:"The ironic opening of Voltaire’s philosophical tale, introducing the na\xefve hero Candide. (Opening)",summary_hi:"वोल्तेयर की दार्शनिक कथा का व्यंग्यपूर्ण आरंभ, जिसमें भोले नायक कैंडिड का परिचय है। (आरंभ)",source:"Public domain",passages:[{fr:"Il y avait en Westphalie, dans le ch\xe2teau de M. le baron de Thunder-ten-tronckh, un jeune gar\xe7on \xe0 qui la nature avait donn\xe9 les mœurs les plus douces.",en:"There lived in Westphalia, in the castle of the Baron of Thunder-ten-tronckh, a young boy on whom nature had bestowed the gentlest of characters."},{fr:"Sa physionomie annon\xe7ait son \xe2me. Il avait le jugement assez droit, avec l’esprit le plus simple ; c’est, je crois, par cette raison qu’on le nommait Candide.",en:"His face reflected his soul. He had rather sound judgment, with the simplest of minds; it is, I believe, for this reason that he was called Candide."}],glossary:[{fr:"les mœurs",en:"character, manners, customs",hi:"स्वभाव; रीति-रिवाज"},{fr:"la physionomie",en:"facial appearance, expression",hi:"चेहरे का भाव"},{fr:"annoncer",en:"to announce, to reveal",hi:"प्रकट करना"},{fr:"le jugement",en:"judgement",hi:"विवेक"},{fr:"l’esprit",en:"mind, wit",hi:"बुद्धि; मन"},{fr:"nommer",en:"to name, to call",hi:"नाम देना"}],questions:[{q:"Why is the hero called Candide?",options:["Because he is rich","Because of his simple, na\xefve mind","Because he is a baron","Because he is a soldier"],correct:1,explain:"Voltaire says ironically that his \xab esprit le plus simple \xbb explains the name; \xab candide \xbb means na\xefve and sincere."}]},{slug:"madame-bovary-ouverture",kind:"story",title:"Madame Bovary, premi\xe8re partie",title_en:"Madame Bovary, Part One",author:"Gustave Flaubert",year:"1857",level:"B2",minutes:6,summary_en:"The first lines of the great realist novel: a new boy arrives in a classroom. (Opening)",summary_hi:"महान यथार्थवादी उपन्यास की पहली पंक्तियाँ: कक्षा में एक नया लड़का आता है। (आरंभ)",source:"Public domain",passages:[{fr:"Nous \xe9tions \xe0 l’\xc9tude, quand le Proviseur entra, suivi d’un nouveau habill\xe9 en bourgeois et d’un gar\xe7on de classe qui portait un grand pupitre.",en:"We were in study hall when the Headmaster came in, followed by a new boy dressed in ordinary clothes and by a school attendant carrying a large desk."},{fr:"Ceux qui dormaient se r\xe9veill\xe8rent, et chacun se leva comme surpris dans son travail.",en:"Those who had been sleeping woke up, and everyone stood up as if caught at work."}],glossary:[{fr:"l’\xc9tude",en:"study hall",hi:"अध्ययन कक्ष"},{fr:"le Proviseur",en:"headmaster (lyc\xe9e)",hi:"प्रधानाचार्य"},{fr:"un nouveau",en:"a new pupil",hi:"नया विद्यार्थी"},{fr:"le pupitre",en:"school desk",hi:"डेस्क"},{fr:"entra, se r\xe9veill\xe8rent, se leva",en:"pass\xe9 simple (narrative past, literary)",hi:"पासे सिंपल (साहित्यिक भूतकाल)"}],questions:[{q:"\xab Le Proviseur entra \xbb is in which tense?",options:["Pass\xe9 compos\xe9","Pass\xe9 simple","Imparfait","Futur ant\xe9rieur"],correct:1,explain:"The pass\xe9 simple (entra, se leva) tells completed actions in literary narration; \xab dormaient \xbb is imparfait for background."}]},{slug:"la-parure-ouverture",kind:"story",title:"La Parure",title_en:"The Necklace",author:"Guy de Maupassant",year:"1884",level:"B2",minutes:6,summary_en:"The opening of one of the most famous short stories in French: a woman who feels born for a richer life. (Opening)",summary_hi:"फ़्रेंच की सबसे मशहूर लघुकथाओं में से एक का आरंभ: एक स्त्री जो खुद को अमीर जीवन के लिए बनी मानती है। (आरंभ)",source:"Public domain",passages:[{fr:"C’\xe9tait une de ces jolies et charmantes filles, n\xe9es, comme par une erreur du destin, dans une famille d’employ\xe9s.",en:"She was one of those pretty, charming girls born, as if by an error of fate, into a family of clerks."},{fr:"Elle n’avait pas de dot, pas d’esp\xe9rances, aucun moyen d’\xeatre connue, comprise, aim\xe9e, \xe9pous\xe9e par un homme riche et distingu\xe9 ; et elle se laissa marier avec un petit commis du minist\xe8re de l’Instruction publique.",en:"She had no dowry, no prospects, no means of being known, understood, loved and married by a rich and distinguished man; and she let herself be married to a minor clerk at the Ministry of Public Education."}],glossary:[{fr:"la parure",en:"a set of jewellery",hi:"गहनों का सेट"},{fr:"le destin",en:"fate",hi:"भाग्य"},{fr:"la dot",en:"dowry",hi:"दहेज़"},{fr:"\xe9pouser",en:"to marry (someone)",hi:"विवाह करना"},{fr:"un commis",en:"a junior clerk",hi:"छोटा क्लर्क"},{fr:"se laisser marier",en:"to let oneself be married",hi:"खुद को ब्याह जाने देना"}],questions:[{q:"What is the heroine’s main problem?",options:["She is ill","She feels she was born into the wrong social class","She has too many children","She hates Paris"],correct:1,explain:"\xab N\xe9es, comme par une erreur du destin, dans une famille d’employ\xe9s \xbb — she believes she deserves a richer life."}]},{slug:"pensees-et-maximes",kind:"maxims",title:"Pens\xe9es et maximes",title_en:"Thoughts and Maxims",author:"Pascal, La Rochefoucauld, Descartes, Rousseau, Voltaire",year:"1637–1762",level:"C1",minutes:8,summary_en:"Eight famous sentences from the golden age of French thought, each a model of concision.",summary_hi:"फ़्रेंच चिंतन के स्वर्ण युग के आठ प्रसिद्ध वाक्य, हर एक संक्षिप्तता का आदर्श।",source:"Public domain",passages:[{fr:"\xab Le cœur a ses raisons, que la raison ne conna\xeet point. \xbb\n— Blaise Pascal",en:"“The heart has its reasons, which reason does not know.”\n— Blaise Pascal"},{fr:"\xab L’homme n’est qu’un roseau, le plus faible de la nature ; mais c’est un roseau pensant. \xbb\n— Blaise Pascal",en:"“Man is only a reed, the weakest in nature; but he is a thinking reed.”\n— Blaise Pascal"},{fr:"\xab Nous avons tous assez de force pour supporter les maux d’autrui. \xbb\n— La Rochefoucauld",en:"“We all have enough strength to bear the misfortunes of others.”\n— La Rochefoucauld"},{fr:"\xab L’hypocrisie est un hommage que le vice rend \xe0 la vertu. \xbb\n— La Rochefoucauld",en:"“Hypocrisy is a tribute that vice pays to virtue.”\n— La Rochefoucauld"},{fr:"\xab Je pense, donc je suis. \xbb\n— Ren\xe9 Descartes",en:"“I think, therefore I am.”\n— Ren\xe9 Descartes"},{fr:"\xab L’homme est n\xe9 libre, et partout il est dans les fers. \xbb\n— Jean-Jacques Rousseau",en:"“Man is born free, and everywhere he is in chains.”\n— Jean-Jacques Rousseau"},{fr:"\xab Il faut cultiver notre jardin. \xbb\n— Voltaire",en:"“We must cultivate our garden.”\n— Voltaire"},{fr:"\xab Que sais-je ? \xbb\n— Michel de Montaigne",en:"“What do I know?”\n— Michel de Montaigne"}],glossary:[{fr:"ne… point",en:"not at all (literary “ne… pas”)",hi:"बिल्कुल नहीं"},{fr:"un roseau",en:"a reed",hi:"नरकट"},{fr:"les maux d’autrui",en:"other people’s ills",hi:"दूसरों के कष्ट"},{fr:"rendre hommage \xe0",en:"to pay tribute to",hi:"को श्रद्धांजलि देना"},{fr:"les fers",en:"chains, shackles",hi:"बेड़ियाँ"},{fr:"cultiver",en:"to cultivate, to tend",hi:"सँवारना; खेती करना"}],questions:[{q:"Which author said \xab Je pense, donc je suis \xbb?",options:["Pascal","Descartes","Voltaire","Montaigne"],correct:1,explain:"Descartes, in the Discours de la m\xe9thode (1637): the “cogito”, the foundation of modern philosophy."},{q:"\xab Il faut cultiver notre jardin \xbb (Candide) suggests that…",options:["We should become farmers only","We should focus on practical, useful work rather than empty speculation","We should leave our homes","Gardens are dangerous"],correct:1,explain:"Voltaire’s conclusion: stop idle metaphysics and tend to your own work and community."}]}],A=(e,s,t,i)=>({level:e,topic:s,en:t,fr:i}),I=[A("A1","Greetings","Hello, my name is Anna.","Bonjour, je m’appelle Anna."),A("A1","Identity","I am a student.","Je suis \xe9tudiant."),A("A1","Greetings","How are you?","Comment allez-vous ?"),A("A1","Home","I live in Paris.","J’habite \xe0 Paris."),A("A1","Family","She has two brothers.","Elle a deux fr\xe8res."),A("A1","Feelings","We are hungry.","Nous avons faim."),A("A1","Travel","Where is the station?","O\xf9 est la gare ?"),A("A1","Food","The coffee is hot.","Le caf\xe9 est chaud."),A("A1","Likes","I like music.","J’aime la musique."),A("A1","Feelings","He is not tired.","Il n’est pas fatigu\xe9."),A("A1","Time","What time is it?","Quelle heure est-il ?"),A("A1","Family","My mother is a doctor.","Ma m\xe8re est m\xe9decin."),A("A1","Food","I would like a glass of water.","Je voudrais un verre d’eau."),A("A1","Greetings","Thank you very much.","Merci beaucoup."),A("A2","Past","Yesterday I visited the museum.","Hier, j’ai visit\xe9 le mus\xe9e."),A("A2","Future","We are going to travel next week.","Nous allons voyager la semaine prochaine."),A("A2","Daily life","She is looking for her keys.","Elle cherche ses cl\xe9s."),A("A2","Communication","I do not understand this word.","Je ne comprends pas ce mot."),A("A2","Politeness","Can you help me, please?","Pouvez-vous m’aider, s’il vous pla\xeet ?"),A("A2","Past","It was raining when we left.","Il pleuvait quand nous sommes partis."),A("A2","Routine","He wakes up at seven every morning.","Il se r\xe9veille \xe0 sept heures tous les matins."),A("A2","Past","I have already eaten.","J’ai d\xe9j\xe0 mang\xe9."),A("A2","Comparison","This restaurant is better than that one.","Ce restaurant est meilleur que celui-l\xe0."),A("A2","Directions","Turn left at the pharmacy.","Tournez \xe0 gauche \xe0 la pharmacie."),A("A2","Shopping","How much does this cost?","Combien \xe7a co\xfbte ?"),A("A2","Places","My friends live far from here.","Mes amis habitent loin d’ici."),A("B1","Conditions","If I have time, I will come.","Si j’ai le temps, je viendrai."),A("B1","Wishes","I would like to learn Spanish.","Je voudrais apprendre l’espagnol."),A("B1","Reported speech","She told me that she was tired.","Elle m’a dit qu’elle \xe9tait fatigu\xe9e."),A("B1","Subjunctive","It is necessary that you come early.","Il faut que tu viennes t\xf4t."),A("B1","Past habits","When I was young, I played football.","Quand j’\xe9tais jeune, je jouais au football."),A("B1","Duration","I have been living here for three years.","J’habite ici depuis trois ans."),A("B1","Pronouns","He gave me the book yesterday.","Il m’a donn\xe9 le livre hier."),A("B1","Concession","Although it is expensive, I will buy it.","Bien que ce soit cher, je l’ach\xe8terai."),A("B1","Opinion","I think that he is right.","Je pense qu’il a raison."),A("B1","Regret","We should have left earlier.","Nous aurions d\xfb partir plus t\xf4t."),A("B1","Relative clauses","The film that I saw was excellent.","Le film que j’ai vu \xe9tait excellent."),A("B1","Reported speech","She asked me where I worked.","Elle m’a demand\xe9 o\xf9 je travaillais."),A("B2","Conditions","Had I known, I would have stayed.","Si j’avais su, je serais rest\xe9."),A("B2","Opinion","It seems to me that the situation is getting worse.","Il me semble que la situation empire."),A("B2","Concession","Whatever happens, I will stay with you.","Quoi qu’il arrive, je resterai avec toi."),A("B2","Proportion","The more I read, the more I learn.","Plus je lis, plus j’apprends."),A("B2","Comparison","He speaks as if he knew everything.","Il parle comme s’il savait tout."),A("B2","Concession","Despite the rain, the match took place.","Malgr\xe9 la pluie, le match a eu lieu."),A("B2","Relative clauses","This is the book I was talking about.","C’est le livre dont je parlais."),A("B2","Regret","She regrets not having come.","Elle regrette de ne pas \xeatre venue."),A("B2","Work","We must find a solution as soon as possible.","Nous devons trouver une solution le plus t\xf4t possible."),A("B2","Subjunctive","I doubt that he will succeed.","Je doute qu’il r\xe9ussisse."),A("C1","Concession","Even if he were to resign, nothing would change.","Quand bien m\xeame il d\xe9missionnerait, rien ne changerait."),A("C1","Formal register","One cannot overstate the importance of this reform.","On ne saurait exag\xe9rer l’importance de cette r\xe9forme."),A("C1","Inversion","No sooner had she arrived than the meeting began.","\xc0 peine \xe9tait-elle arriv\xe9e que la r\xe9union commen\xe7a."),A("C1","Subjunctive","Whatever his motives may be, his act remains unjustifiable.","Quels que soient ses motifs, son acte demeure injustifiable."),A("C1","Subjunctive","He would have liked us to be present.","Il aurait aim\xe9 que nous soyons pr\xe9sents."),A("C1","Formal register","It is to be feared that the crisis will deepen.","Il est \xe0 craindre que la crise ne s’aggrave."),A("C1","Rhetoric","Far from calming the debate, his remarks inflamed it.","Loin d’apaiser le d\xe9bat, ses propos l’ont enflamm\xe9."),A("C1","Formal register","To my knowledge, the report has not been published.","\xc0 ma connaissance, le rapport n’a pas \xe9t\xe9 publi\xe9.")],E=[{slug:"etre-avoir",level:"A1",title:"\xcatre and avoir (to be, to have)",summary:"The two most important verbs in French. They are irregular and also act as auxiliaries for past tenses.",rules:[{rule:"\xcatre describes who or what someone is: identity, job, nationality, state.",examples:[{fr:"Je suis \xe9tudiant.",en:"I am a student."},{fr:"Elle est fran\xe7aise.",en:"She is French."}]},{rule:"Avoir expresses possession, and also age and some feelings (faim, soif, peur, chaud, froid).",examples:[{fr:"J’ai vingt ans.",en:"I am twenty."},{fr:"Nous avons faim.",en:"We are hungry."}]}],tables:[{caption:"Pr\xe9sent",headers:["Pronoun","\xeatre","avoir"],rows:[["je / j’","suis","ai"],["tu","es","as"],["il / elle / on","est","a"],["nous","sommes","avons"],["vous","\xeates","avez"],["ils / elles","sont","ont"]]}],tips:["Age uses avoir: \xab J’ai 25 ans \xbb, never \xab je suis 25 ans \xbb.","Liaison: \xab vous avez \xbb is pronounced vou-z-avez."]},{slug:"articles-gender",level:"A1",title:"Articles and gender",summary:"Every French noun is masculine or feminine, and the article tells you which.",rules:[{rule:"Definite articles (the): le (m), la (f), l’ (before a vowel), les (plural).",examples:[{fr:"le livre, la table, l’ami, les enfants",en:"the book, the table, the friend, the children"}]},{rule:"Indefinite articles (a/an/some): un (m), une (f), des (plural).",examples:[{fr:"Un caf\xe9 et une baguette, s’il vous pla\xeet.",en:"A coffee and a baguette, please."}]},{rule:"Partitive (some, an amount of): du, de la, de l’.",examples:[{fr:"Je bois du caf\xe9 et de l’eau.",en:"I drink (some) coffee and water."}]}],tips:["Learn each noun with its article: la maison, le jardin.","Many nouns ending in -tion, -t\xe9, -ie are feminine; those ending in -age, -ment, -eau are often masculine."]},{slug:"present-er-verbs",level:"A1",title:"Pr\xe9sent of regular -er verbs",summary:"About 90% of French verbs end in -er and follow one pattern.",rules:[{rule:"Remove -er from the infinitive and add the endings -e, -es, -e, -ons, -ez, -ent.",examples:[{fr:"Je parle fran\xe7ais.",en:"I speak French."},{fr:"Nous habitons \xe0 Lyon.",en:"We live in Lyon."}]}],tables:[{caption:"parler (to speak)",headers:["Pronoun","Form"],rows:[["je","parle"],["tu","parles"],["il / elle / on","parle"],["nous","parlons"],["vous","parlez"],["ils / elles","parlent"]]}],tips:["The endings -e, -es, -ent are silent: je parle, tu parles and ils parlent sound the same.","Verbs in -ger and -cer add a letter before -ons: nous mangeons, nous commen\xe7ons."]},{slug:"negation-questions",level:"A1",title:"Negation and questions",summary:"Wrap the verb with ne… pas, and ask questions with est-ce que, intonation or inversion.",rules:[{rule:"Negation: ne + verb + pas (ne becomes n’ before a vowel).",examples:[{fr:"Je ne parle pas allemand.",en:"I do not speak German."},{fr:"Il n’est pas fatigu\xe9.",en:"He is not tired."}]},{rule:"Questions: raise your voice, add est-ce que, or invert the verb and pronoun (more formal).",examples:[{fr:"Tu viens ?",en:"Are you coming?"},{fr:"Est-ce que tu viens ?",en:"Are you coming?"},{fr:"Venez-vous ?",en:"Are you coming? (formal)"}]}],tips:["In speech, ne is often dropped: \xab Je sais pas \xbb. Keep it in writing.","Question words: qui, que, o\xf9, quand, comment, pourquoi, combien."]},{slug:"irregular-aller-faire",level:"A1",title:"Aller, faire, venir, prendre",summary:"Four irregular verbs you will use every day.",rules:[{rule:"Aller (to go) also builds the near future: aller + infinitive.",examples:[{fr:"Je vais \xe0 l’\xe9cole.",en:"I go to school."},{fr:"Nous allons partir.",en:"We are going to leave."}]}],tables:[{caption:"Pr\xe9sent",headers:["Pronoun","aller","faire","venir","prendre"],rows:[["je","vais","fais","viens","prends"],["tu","vas","fais","viens","prends"],["il / elle / on","va","fait","vient","prend"],["nous","allons","faisons","venons","prenons"],["vous","allez","faites","venez","prenez"],["ils / elles","vont","font","viennent","prennent"]]}],tips:["Faire appears in weather (il fait beau), activities (faire du sport) and chores (faire les courses)."]},{slug:"passe-compose",level:"A2",title:"Pass\xe9 compos\xe9",summary:"The main tense for completed past actions: auxiliary (avoir or \xeatre) + past participle.",rules:[{rule:"Most verbs use avoir: j’ai mang\xe9, tu as fini, nous avons parl\xe9.",examples:[{fr:"Hier, j’ai visit\xe9 le mus\xe9e.",en:"Yesterday I visited the museum."}]},{rule:"Verbs of motion and reflexive verbs use \xeatre, and the participle agrees with the subject.",examples:[{fr:"Elle est arriv\xe9e \xe0 huit heures.",en:"She arrived at eight."},{fr:"Nous nous sommes lev\xe9s t\xf4t.",en:"We got up early."}]}],tables:[{caption:"Irregular participles",headers:["Infinitive","Participle"],rows:[["avoir","eu"],["\xeatre","\xe9t\xe9"],["faire","fait"],["prendre","pris"],["voir","vu"],["pouvoir","pu"],["vouloir","voulu"],["\xe9crire","\xe9crit"]]},{caption:"Verbs that take \xeatre (DR MRS VANDERTRAMP)",headers:["Group","Examples"],rows:[["Motion","aller, venir, arriver, partir, entrer, sortir"],["Up / down","monter, descendre, tomber"],["Life","na\xeetre, mourir, rester, devenir"],["Return","rentrer, retourner"]]}],tips:["With \xeatre, agree the participle: elles sont parties.","Negation wraps the auxiliary: je n’ai pas mang\xe9."]},{slug:"futur-proche-pronouns",level:"A2",title:"Near future and direct object pronouns",summary:"Talk about what you are about to do, and avoid repetition with le, la, les.",rules:[{rule:"Futur proche: aller (pr\xe9sent) + infinitive.",examples:[{fr:"Il va pleuvoir.",en:"It is going to rain."}]},{rule:"Direct object pronouns: me, te, le/la, nous, vous, les — placed before the conjugated verb.",examples:[{fr:"Je le vois.",en:"I see him / it."},{fr:"Je ne les connais pas.",en:"I do not know them."},{fr:"Je vais la voir demain.",en:"I am going to see her tomorrow."}]}],tips:["In the pass\xe9 compos\xe9, the pronoun goes before the auxiliary and the participle agrees: \xab Je l’ai vue \xbb."]},{slug:"imparfait",level:"B1",title:"Imparfait vs pass\xe9 compos\xe9",summary:"Imparfait paints the scene and habits; pass\xe9 compos\xe9 tells the events.",rules:[{rule:"Imparfait: stem of nous (pr\xe9sent) minus -ons + -ais, -ais, -ait, -ions, -iez, -aient.",examples:[{fr:"Quand j’\xe9tais petit, nous allions \xe0 la mer.",en:"When I was little, we used to go to the sea."}]},{rule:"Use imparfait for description, habits and ongoing background; use pass\xe9 compos\xe9 for a precise event that interrupts.",examples:[{fr:"Il pleuvait quand nous sommes sortis.",en:"It was raining when we went out."}]}],tables:[{caption:"\xeatre, avoir, faire \xe0 l’imparfait",headers:["Pronoun","\xeatre","avoir","faire"],rows:[["je","\xe9tais","avais","faisais"],["tu","\xe9tais","avais","faisais"],["il / elle","\xe9tait","avait","faisait"],["nous","\xe9tions","avions","faisions"],["vous","\xe9tiez","aviez","faisiez"],["ils / elles","\xe9taient","avaient","faisaient"]]}],tips:["Trigger words for imparfait: souvent, toujours, d’habitude, chaque jour, \xe0 cette \xe9poque."]},{slug:"futur-conditionnel",level:"B1",title:"Futur simple and conditionnel",summary:"Both are built on the infinitive (or irregular stem). Futur states facts to come; conditionnel states hypotheticals and politeness.",rules:[{rule:"Futur: infinitive + -ai, -as, -a, -ons, -ez, -ont.",examples:[{fr:"Demain, nous partirons t\xf4t.",en:"Tomorrow we will leave early."}]},{rule:"Conditionnel: the same stem + imparfait endings (-ais, -ait…). Used for polite requests and hypotheses.",examples:[{fr:"Je voudrais un caf\xe9.",en:"I would like a coffee."},{fr:"Si j’avais le temps, je voyagerais.",en:"If I had time, I would travel."}]}],tables:[{caption:"Irregular stems (futur and conditionnel)",headers:["Verb","Stem","Example"],rows:[["\xeatre","ser-","je serai / je serais"],["avoir","aur-","j’aurai / j’aurais"],["aller","ir-","j’irai / j’irais"],["faire","fer-","je ferai / je ferais"],["pouvoir","pourr-","je pourrai / je pourrais"],["venir","viendr-","je viendrai / je viendrais"],["voir","verr-","je verrai / je verrais"]]}],tips:["If-clauses: si + pr\xe9sent → futur; si + imparfait → conditionnel."]},{slug:"subjonctif-present",level:"B1",title:"Subjonctif pr\xe9sent",summary:"The mood of doubt, wish, necessity and emotion, used after que.",rules:[{rule:"Triggers: il faut que, vouloir que, bien que, pour que, avant que, douter que, \xeatre content que…",examples:[{fr:"Il faut que tu viennes.",en:"You must come."},{fr:"Bien qu’il soit fatigu\xe9, il travaille.",en:"Although he is tired, he is working."}]},{rule:"Formation: ils-stem of the pr\xe9sent + -e, -es, -e, -ions, -iez, -ent.",examples:[{fr:"que je parle, que nous finissions",en:"that I speak, that we finish"}]}],tables:[{caption:"Irregular subjunctives",headers:["Pronoun","\xeatre","avoir","faire","aller"],rows:[["que je","sois","aie","fasse","aille"],["que tu","sois","aies","fasses","ailles"],["qu’il / elle","soit","ait","fasse","aille"],["que nous","soyons","ayons","fassions","allions"],["que vous","soyez","ayez","fassiez","alliez"],["qu’ils / elles","soient","aient","fassent","aillent"]]}],tips:["No subjunctive when the subject is the same: \xab Je veux partir \xbb (not \xab que je parte \xbb).","Certainty (je pense que, je sais que) → indicatif; doubt (je doute que) → subjonctif."]},{slug:"pronoms-relatifs",level:"B2",title:"Relative pronouns: qui, que, dont, o\xf9, lequel",summary:"Link clauses elegantly. The choice depends on the role of the noun in the relative clause.",rules:[{rule:"qui = subject; que = direct object; o\xf9 = place or time; dont = replaces de + noun.",examples:[{fr:"L’homme qui parle est mon oncle.",en:"The man who is speaking is my uncle."},{fr:"Le livre que je lis est passionnant.",en:"The book I am reading is gripping."},{fr:"C’est le livre dont je parlais.",en:"It is the book I was talking about."}]},{rule:"After a preposition, use lequel / laquelle / lesquels / lesquelles (auquel, duquel…).",examples:[{fr:"La raison pour laquelle il est parti reste inconnue.",en:"The reason why he left remains unknown."}]}],tips:["If the verb after the pronoun takes \xab de \xbb (parler de, avoir besoin de), use dont.","That agreement: \xab la lettre que j’ai \xe9crite \xbb — the participle agrees with the preceding object."]},{slug:"plus-que-parfait-hypotheses",level:"B2",title:"Plus-que-parfait and past hypotheses",summary:"Talk about what happened before another past event, and imagine different pasts.",rules:[{rule:"Plus-que-parfait: imparfait of avoir/\xeatre + participle.",examples:[{fr:"Quand je suis arriv\xe9, il \xe9tait d\xe9j\xe0 parti.",en:"When I arrived, he had already left."}]},{rule:"Unreal past: si + plus-que-parfait → conditionnel pass\xe9.",examples:[{fr:"Si j’avais su, je serais rest\xe9.",en:"If I had known, I would have stayed."}]}],tips:["Conditionnel pass\xe9 = conditionnel of avoir/\xeatre + participle: \xab j’aurais d\xfb \xbb, \xab nous serions partis \xbb."]},{slug:"concordance-passe-simple",level:"C1",title:"Pass\xe9 simple and sequence of tenses",summary:"The literary narrative past, and how tenses line up in formal writing.",rules:[{rule:"Pass\xe9 simple is used in literature and history for completed actions. -er verbs: -ai, -as, -a, -\xe2mes, -\xe2tes, -\xe8rent.",examples:[{fr:"Il entra, regarda autour de lui et sourit.",en:"He came in, looked around and smiled."}]},{rule:"Sequence: the main verb’s tense decides whether you use the pr\xe9sent or the imparfait subjunctive (rare today).",examples:[{fr:"Il fallait qu’il part\xeet.",en:"He had to leave. (literary imparfait du subjonctif)"}]}],tables:[{caption:"Pass\xe9 simple of common verbs (il / ils)",headers:["Infinitive","il / elle","ils / elles"],rows:[["\xeatre","fut","furent"],["avoir","eut","eurent"],["faire","fit","firent"],["aller","alla","all\xe8rent"],["venir","vint","vinrent"],["dire","dit","dirent"]]}],tips:["You will meet the pass\xe9 simple mostly in the 3rd person. Learn to recognise it before producing it.","Modern writing replaces the imparfait du subjonctif with the pr\xe9sent: \xab Il fallait qu’il parte \xbb."]},{slug:"registre-soutenu",level:"C1",title:"Formal register and stylistic devices",summary:"Inversion, ne expl\xe9tif and concessive structures that give your French an educated tone.",rules:[{rule:"Inversion after adverbs: \xe0 peine, peut-\xeatre, sans doute, aussi (therefore).",examples:[{fr:"\xc0 peine \xe9tait-elle arriv\xe9e que la r\xe9union commen\xe7a.",en:"No sooner had she arrived than the meeting began."}]},{rule:"Concession with quel que soit / quoi que + subjunctive, and loin de + infinitive.",examples:[{fr:"Quels que soient ses motifs, son acte demeure injustifiable.",en:"Whatever his motives, his act remains unjustifiable."}]},{rule:"On ne saurait + infinitive = “one cannot”: a formal alternative to ne pas pouvoir.",examples:[{fr:"On ne saurait exag\xe9rer l’importance de cette r\xe9forme.",en:"One cannot overstate the importance of this reform."}]}],tips:["Ne expl\xe9tif: after craindre que, avoir peur que, avant que (formal): \xab Je crains qu’il ne vienne \xbb. It is not a negation."]}],L=(e,s,t)=>({fr:e,en:s,hi:t}),T=function(e,s){for(var t=arguments.length,i=Array(t>2?t-2:0),a=2;a<t;a++)i[a-2]=arguments[a];return{rule:e,rule_hi:s,examples:i}},F=(e,s,t,i)=>({q:e,options:s,correct:t,explain:i}),S=function(e,s){for(var t=arguments.length,i=Array(t>2?t-2:0),a=2;a<t;a++)i[a-2]=arguments[a];return{caption:e,headers:s,rows:i}},P=[{slug:"adjectifs-accord",level:"A1",title:"Adjectives: gender and number",title_hi:"विशेषण: लिंग और वचन",summary:"Adjectives agree with the noun: add -e for feminine, -s for plural.",summary_hi:"विशेषण संज्ञा के अनुसार बदलता है: स्त्रीलिंग में -e, बहुवचन में -s जोड़ें।",rules:[T("Feminine: usually add -e. If it already ends in -e, nothing changes.","स्त्रीलिंग: आमतौर पर -e जोड़ें। अगर पहले से -e है तो कुछ नहीं बदलता।",L("Il est grand. Elle est grande.","He is tall. She is tall.","वह (पु.) लंबा है। वह (स्त्री) लंबी है।"),L("Un gar\xe7on timide, une fille timide.","A shy boy, a shy girl.","एक शर्मीला लड़का, एक शर्मीली लड़की।")),T("Plural: add -s (words ending in -s/-x stay the same). Most adjectives come AFTER the noun.","बहुवचन: -s जोड़ें। ज़्यादातर विशेषण संज्ञा के बाद आते हैं।",L("Des voitures rouges.","Red cars.","लाल गाड़ियाँ।"),L("Un livre int\xe9ressant.","An interesting book.","एक दिलचस्प किताब।"))],tables:[S("Irregular feminines",["Masculine","Feminine","Hindi"],["beau","belle","सुंदर"],["nouveau","nouvelle","नया"],["blanc","blanche","सफ़ेद"],["heureux","heureuse","खुश"],["sportif","sportive","खिलाड़ी/खेल-प्रेमी"],["gentil","gentille","दयालु"])],tips:["Short common adjectives go BEFORE the noun: petit, grand, beau, bon, jeune, vieux, nouveau.","Colours and nationalities go after the noun: une robe bleue, un ami indien."],tips_hi:["छोटे आम विशेषण संज्ञा से पहले आते हैं (petit, grand, beau, bon)।","रंग और राष्ट्रीयता वाले विशेषण संज्ञा के बाद आते हैं।"],quiz:[F("Elle est ___.",["content","contente","contents"],1,"Feminine singular adds -e."),F("Des filles ___.",["heureux","heureuses","heureuse"],1,"heureux → heureuse → heureuses (fem. plural).")]},{slug:"nombres-heure",level:"A1",title:"Numbers, date and time",title_hi:"संख्याएँ, तारीख़ और समय",summary:"Count, give the date and tell the time. French uses 'vingt' and 'quatre-vingts' patterns.",summary_hi:"गिनती, तारीख़ और समय बताना। फ्रेंच में 70 = 60+10 और 80 = 4\xd720 जैसे पैटर्न हैं।",rules:[T("Numbers 70–99 are built on 60 and 20.","70–99 की संख्याएँ 60 और 20 पर बनती हैं।",L("soixante-dix (70), quatre-vingts (80), quatre-vingt-dix (90)","seventy, eighty, ninety","सत्तर, अस्सी, नब्बे"),L("quatre-vingt-quinze","ninety-five (4\xd720 + 15)","पचानवे")),T("Time: \xab Il est + heure(s) \xbb. Use 'et quart', 'et demie', 'moins le quart'.","समय: \xab Il est + heure \xbb। quart = सवा/पौन, demie = साढ़े।",L("Il est huit heures et quart.","It is 8:15.","सवा आठ बजे हैं।"),L("Il est midi moins le quart.","It is 11:45.","पौने बारह बजे हैं।")),T("Date: le + number + month. Only the 1st uses 'premier'.","तारीख़: le + संख्या + महीना। सिर्फ़ 1 के लिए premier।",L("Aujourd’hui, c’est le 1er mai.","Today is 1 May.","आज 1 मई है।"),L("Je suis n\xe9 le 12 ao\xfbt.","I was born on 12 August.","मेरा जन्म 12 अगस्त को हुआ।"))],tables:[S("Basics",["Number","French","Hindi"],["1","un / une","एक"],["2","deux","दो"],["3","trois","तीन"],["4","quatre","चार"],["5","cinq","पाँच"],["10","dix","दस"],["20","vingt","बीस"],["100","cent","सौ"],["1000","mille","हज़ार"])],tips:["TEF/TCF listening: practise hearing 60, 70, 80, 90 — they are the commonest traps.","Days and months are not capitalised in French: lundi, janvier."],tips_hi:["सुनने की परीक्षा में 60/70/80/90 सबसे बड़ा जाल हैं — रोज़ सुनने का अभ्यास करें।","दिन और महीने छोटे अक्षर से लिखे जाते हैं।"],quiz:[F("80 en fran\xe7ais :",["soixante-dix","quatre-vingts","huit-dix"],1,"80 = 4 \xd7 20."),F("8h45 :",["neuf heures moins le quart","huit heures et quart","neuf heures et quart"],0,"8:45 = 9h moins le quart.")]},{slug:"cest-il-est",level:"A1",title:"C’est vs Il est",title_hi:"C’est और Il est में फ़र्क",summary:"Use c’est to identify/present, il est to describe or give a profession without article.",summary_hi:"c’est = पहचान/परिचय (article के साथ), il est = वर्णन या पेशा (बिना article)।",rules:[T("C’est + article/name/stressed pronoun: identifies.","c’est + article/नाम: किसी की पहचान बताता है।",L("C’est un m\xe9decin. C’est Paul. C’est moi.","He is a doctor. It is Paul. It's me.","यह डॉक्टर है। यह पॉल है। यह मैं हूँ।")),T("Il/Elle est + profession or adjective (no article).","il/elle est + पेशा या विशेषण (बिना article)।",L("Il est m\xe9decin. Elle est grande.","He is a doctor. She is tall.","वह डॉक्टर है। वह लंबी है।")),T("C’est + adjective talks about an idea or situation (masculine).","c’est + विशेषण किसी स्थिति के बारे में बोलता है।",L("C’est facile. C’est important.","It's easy. It's important.","यह आसान है। यह ज़रूरी है।"))],tips:["If there is an article (un, une, le), choose c’est.","Plural: ce sont des \xe9tudiants (but c’est is accepted in speech)."],tips_hi:["अगर article (un, une, le) है तो c’est चुनें।"],quiz:[F("___ une actrice.",["Elle est","C’est"],1,"Article 'une' → c’est."),F("___ avocat.",["Il est","C’est"],0,"Profession without article → il est.")]},{slug:"possessifs-demonstratifs",level:"A1",title:"Possessives and demonstratives",title_hi:"स्वामित्व और संकेतवाचक शब्द",summary:"mon/ma/mes (my) and ce/cet/cette/ces (this/these).",summary_hi:"mon/ma/mes = मेरा/मेरी, ce/cette/ces = यह/ये। ये संज्ञा के लिंग और वचन से तय होते हैं (मालिक के लिंग से नहीं)।",rules:[T("Possessives agree with the thing owned, not the owner.","स्वामित्व शब्द वस्तु के लिंग से चलता है, मालिक से नहीं।",L("Sa m\xe8re (his or her mother).","His/her mother.","उसकी माँ (लड़का या लड़की दोनों के लिए)।"),L("Mon amie (before a vowel, feminine uses mon).","My (female) friend.","मेरी सहेली।")),T("Demonstratives: ce (m), cet (m + vowel), cette (f), ces (pl). Add -ci / -l\xe0 to contrast.","ce/cet/cette/ces = यह/ये। -ci पास, -l\xe0 दूर।",L("Ce livre-ci ou ce livre-l\xe0 ?","This book or that book?","यह किताब या वह किताब?"),L("Cet homme et cette femme.","This man and this woman.","यह आदमी और यह औरत।"))],tables:[S("Possessives",["Owner","m. sg","f. sg","plural"],["je","mon","ma","mes"],["tu","ton","ta","tes"],["il/elle","son","sa","ses"],["nous","notre","notre","nos"],["vous","votre","votre","vos"],["ils/elles","leur","leur","leurs"])],tips:["Before a feminine noun starting with a vowel, use mon/ton/son: mon \xe9cole."],tips_hi:["स्वर से शुरू होने वाली स्त्रीलिंग संज्ञा से पहले mon/ton/son लगता है: mon \xe9cole।"],quiz:[F("___ ami (f) s’appelle Julie.",["Ma","Mon","Mes"],1,"Vowel start → mon."),F("___ arbre est grand.",["Ce","Cet","Cette"],1,"cet before vowel (masculine).")]},{slug:"il-y-a-prepositions",level:"A1",title:"Il y a, places and prepositions",title_hi:"Il y a, जगह और prepositions",summary:"Say what exists and where things are. Countries use en/au/aux, cities use \xe0.",summary_hi:"क्या कहाँ है बताना। देश के लिए en/au/aux, शहर के लिए \xe0।",rules:[T("Il y a = there is / there are (never changes).","il y a = है / हैं (कभी नहीं बदलता)।",L("Il y a un caf\xe9 pr\xe8s d’ici.","There is a caf\xe9 nearby.","यहाँ पास में एक कैफ़े है।")),T("Cities: \xe0. Feminine countries: en. Masculine countries: au. Plural: aux.","शहर: \xe0। स्त्रीलिंग देश: en। पुल्लिंग: au। बहुवचन: aux।",L("J’habite \xe0 Montr\xe9al, au Canada.","I live in Montreal, in Canada.","मैं कनाडा के मॉन्ट्रियल में रहता हूँ।"),L("Elle va en France et aux \xc9tats-Unis.","She goes to France and to the USA.","वह फ़्रांस और अमेरिका जा रही है।"))],tables:[S("Location words",["French","English","Hindi"],["devant / derri\xe8re","in front / behind","सामने / पीछे"],["sur / sous","on / under","ऊपर / नीचे"],["\xe0 c\xf4t\xe9 de","next to","बगल में"],["en face de","opposite","सामने (उल्टी तरफ़)"],["pr\xe8s de / loin de","near / far","पास / दूर"])],tips:["Countries ending in -e are feminine (la France, l’Inde) except le Mexique."],tips_hi:["-e पर खत्म होने वाले देश स्त्रीलिंग होते हैं: l’Inde → en Inde।"],quiz:[F("Je vais ___ Inde.",["\xe0","en","au"],1,"l’Inde is feminine → en Inde."),F("Il vit ___ Canada.",["en","au","\xe0"],1,"le Canada → au Canada.")]},{slug:"verbes-ir-re",level:"A1",title:"Pr\xe9sent: -ir, -re and common irregular verbs",title_hi:"वर्तमान काल: -ir, -re और आम अनियमित क्रियाएँ",summary:"finir (-ir), vendre (-re), prendre, pouvoir, vouloir, devoir, savoir, venir.",summary_hi:"finir, vendre, prendre, pouvoir, vouloir, devoir, savoir, venir — रोज़मर्रा की सबसे ज़रूरी क्रियाएँ।",rules:[T("-ir verbs (finir): -is, -is, -it, -issons, -issez, -issent.","-ir क्रियाएँ: -is, -is, -it, -issons, -issez, -issent।",L("Nous finissons \xe0 six heures.","We finish at six.","हम छह बजे खत्म करते हैं।")),T("-re verbs (vendre): -s, -s, —, -ons, -ez, -ent.","-re क्रियाएँ: -s, -s, (कुछ नहीं), -ons, -ez, -ent।",L("Il vend sa voiture.","He sells his car.","वह अपनी गाड़ी बेच रहा है।"))],tables:[S("Key irregular verbs",["","pouvoir","vouloir","devoir","prendre","venir","savoir"],["je","peux","veux","dois","prends","viens","sais"],["tu","peux","veux","dois","prends","viens","sais"],["il","peut","veut","doit","prend","vient","sait"],["nous","pouvons","voulons","devons","prenons","venons","savons"],["vous","pouvez","voulez","devez","prenez","venez","savez"],["ils","peuvent","veulent","doivent","prennent","viennent","savent"])],tips:["Modal verbs are followed by an infinitive: Je veux apprendre le fran\xe7ais.","Savoir = know a fact/skill; conna\xeetre = know a person/place."],tips_hi:["pouvoir/vouloir/devoir के बाद क्रिया का infinitive आता है।","savoir = जानकारी/कौशल, conna\xeetre = व्यक्ति/जगह से परिचित होना।"],quiz:[F("Ils ___ le bus.",["prend","prennent","prenent"],1,"ils prennent."),F("Nous ___ partir.",["pouvons","pouvez","peuvent"],0,"nous pouvons.")]},{slug:"cod-coi",level:"A2",title:"Object pronouns: le, la, les, lui, leur",title_hi:"कर्म सर्वनाम: le, la, les, lui, leur",summary:"Replace nouns so you don’t repeat them. The pronoun goes BEFORE the conjugated verb.",summary_hi:"संज्ञा को दोहराने से बचने के लिए सर्वनाम। यह क्रिया से पहले आता है।",rules:[T("COD (direct object, no preposition): me, te, le/la, nous, vous, les.","COD (बिना preposition): le/la/les।",L("Je regarde le film. → Je le regarde.","I watch it.","मैं इसे देखता हूँ।")),T("COI (person after \xe0): me, te, lui, nous, vous, leur.","COI (व्यक्ति + \xe0): lui, leur।",L("Je parle \xe0 Marie. → Je lui parle.","I speak to her.","मैं उससे बात करता हूँ।"),L("Je ne leur t\xe9l\xe9phone pas.","I don’t call them.","मैं उन्हें फ़ोन नहीं करता।")),T("In the pass\xe9 compos\xe9 the pronoun goes before the auxiliary; the participle agrees with a preceding COD.","pass\xe9 compos\xe9 में सर्वनाम auxiliary से पहले; COD के साथ participle मेल खाता है।",L("Tu as vu Anna ? Oui, je l’ai vue.","Did you see Anna? Yes, I saw her.","क्या तुमने अन्ना को देखा? हाँ, मैंने उसे देखा।"))],tips:["Imperative affirmative: pronoun AFTER the verb with hyphen: Donne-le-moi.","Verbs like t\xe9l\xe9phoner, r\xe9pondre, parler take '\xe0' → lui/leur."],tips_hi:["आदेश (हाँ वाला): सर्वनाम क्रिया के बाद hyphen से: Donne-le-moi।"],quiz:[F("Je ___ \xe9cris. (\xe0 mes parents)",["les","leur","lui"],1,"\xe0 + people (plural) → leur."),F("Il aime Sophie. Il ___ aime.",["la","lui","le"],0,"Direct object feminine → la.")]},{slug:"en-y",level:"A2",title:"The pronouns en and y",title_hi:"सर्वनाम en और y",summary:"en replaces 'de + thing/quantity'; y replaces '\xe0 + thing' or a place.",summary_hi:"en = de + वस्तु/मात्रा की जगह; y = \xe0 + वस्तु या जगह की जगह।",rules:[T("en = of it/of them/some. Keep the number or quantity word.","en = उसमें से/कुछ। संख्या या मात्रा बनी रहती है।",L("Tu veux du pain ? Oui, j’en veux.","Do you want some bread? Yes, I want some.","रोटी चाहिए? हाँ, मुझे चाहिए।"),L("Elle a trois fr\xe8res. Elle en a trois.","She has three brothers.","उसके तीन भाई हैं।")),T("y = there / to it.","y = वहाँ / उसे।",L("Tu vas \xe0 Paris ? Oui, j’y vais.","Going to Paris? Yes, I’m going there.","पेरिस जा रहे हो? हाँ, मैं वहाँ जा रहा हूँ।"),L("Je pense \xe0 mon examen. J’y pense.","I think about it.","मैं इसके बारे में सोचता हूँ।"))],tips:["Order for two pronouns: me/te/nous/vous → le/la/les → lui/leur → y → en.","'penser \xe0' + person uses stressed pronoun: je pense \xe0 lui."],tips_hi:["व्यक्ति के लिए y नहीं, लिखें: je pense \xe0 elle।"],quiz:[F("Tu as des amis ici ? Oui, j’___ ai.",["y","en","les"],1,"des amis → en."),F("Vous allez au cin\xe9ma ? Oui, nous ___ allons.",["y","en","le"],0,"place → y.")]},{slug:"comparatif-superlatif",level:"A2",title:"Comparatives and superlatives",title_hi:"तुलना और सर्वोत्तमता",summary:"plus / moins / aussi … que; le plus / le moins; meilleur and mieux.",summary_hi:"plus … que = ज़्यादा, moins … que = कम, aussi … que = बराबर; le plus = सबसे।",rules:[T("plus / moins / aussi + adjective + que.","plus/moins/aussi + विशेषण + que।",L("Paris est plus grand que Lyon.","Paris is bigger than Lyon.","पेरिस लियों से बड़ा है।"),L("Elle est aussi rapide que lui.","She is as fast as him.","वह उसके जितनी तेज़ है।")),T("Superlative: le/la/les plus/moins + adjective.","सर्वोत्तम: le/la/les plus + विशेषण।",L("C’est la plus belle ville.","It’s the most beautiful city.","यह सबसे सुंदर शहर है।")),T("bon → meilleur (adj.), bien → mieux (adv.).","bon → meilleur (विशेषण), bien → mieux (क्रिया-विशेषण)।",L("Ce g\xe2teau est meilleur. Il chante mieux.","This cake is better. He sings better.","यह केक बेहतर है। वह बेहतर गाता है।"))],tips:["Never say 'plus bon'. Use meilleur.","Quantity: plus de / moins de / autant de + noun."],tips_hi:["'plus bon' कभी नहीं, हमेशा meilleur।"],quiz:[F("Cette pizza est ___ que celle-l\xe0.",["plus bonne","meilleure","mieux"],1,"bon → meilleur."),F("Il parle ___ que moi.",["meilleur","mieux","plus bon"],1,"adverb of 'parler' → mieux.")]},{slug:"interrogation-complete",level:"A2",title:"Asking questions: qui, que, o\xf9, quand, comment, pourquoi",title_hi:"प्रश्न पूछना: कौन, क्या, कहाँ, कब, कैसे, क्यों",summary:"Three styles: intonation, est-ce que, inversion.",summary_hi:"तीन तरीके: आवाज़ ऊँची करके, est-ce que लगाकर, या क्रिया-सर्वनाम उलटकर (औपचारिक)।",rules:[T("Question words: qui (who), que/quoi (what), o\xf9, quand, comment, pourquoi, combien.","प्रश्नवाचक शब्द।",L("O\xf9 habites-tu ?","Where do you live?","तुम कहाँ रहते हो?"),L("Pourquoi est-ce que tu apprends le fran\xe7ais ?","Why are you learning French?","तुम फ़्रेंच क्यों सीख रहे हो?"),L("Combien co\xfbte ce billet ?","How much is this ticket?","यह टिकट कितने का है?")),T("Inversion adds -t- between two vowels.","दो स्वरों के बीच -t- जुड़ता है।",L("Parle-t-il anglais ?","Does he speak English?","क्या वह अंग्रेज़ी बोलता है?"))],tips:["Speaking exam: use est-ce que — safe and natural.","Writing formal letters: prefer inversion."],tips_hi:["बोलने की परीक्षा में est-ce que सुरक्षित है; औपचारिक पत्र में inversion।"],quiz:[F("___ tu pars ? — Demain.",["Quand","O\xf9","Qui"],0,"Demain answers 'when'."),F("Inversion : A-___ mang\xe9 ?",["il t-","t-il","-il"],1,"A-t-il mang\xe9 ?")]},{slug:"imperatif-pronominaux",level:"A2",title:"Imperative and reflexive verbs",title_hi:"आदेशसूचक और आत्मवाचक क्रियाएँ",summary:"Give orders/advice; talk about daily routine with se lever, se coucher…",summary_hi:"आदेश/सलाह देना और दिनचर्या बताना: se r\xe9veiller, se laver, se coucher।",rules:[T("Imperative = present without subject (tu form of -er verbs loses -s).","आदेश = बिना subject के वर्तमान (-er में tu का -s हट जाता है)।",L("Parle plus lentement, s’il te pla\xeet.","Speak more slowly, please.","कृपया धीरे बोलो।"),L("Allons-y !","Let’s go!","चलो चलें!")),T("Reflexive verbs use me/te/se/nous/vous/se; pass\xe9 compos\xe9 uses \xeatre.","आत्मवाचक क्रियाएँ me/te/se; pass\xe9 compos\xe9 में \xeatre।",L("Je me l\xe8ve \xe0 sept heures.","I get up at seven.","मैं सात बजे उठता हूँ।"),L("Elle s’est couch\xe9e tard.","She went to bed late.","वह देर से सोई।"))],tables:[S("Daily routine",["French","English","Hindi"],["se r\xe9veiller","to wake up","जागना"],["se lever","to get up","उठना"],["se doucher","to shower","नहाना"],["s’habiller","to get dressed","कपड़े पहनना"],["se coucher","to go to bed","सोने जाना"])],tips:["Negative imperative: Ne te d\xe9p\xeache pas ! Affirmative: D\xe9p\xeache-toi !"],tips_hi:["निषेध में: Ne te d\xe9p\xeache pas! हाँ में: D\xe9p\xeache-toi!"],quiz:[F("(tu, parler) ___ plus fort !",["Parles","Parle","Parler"],1,"-er imperative drops the -s."),F("Hier, elle ___ lev\xe9e t\xf4t.",["a","s’est","est"],1,"elle s’est lev\xe9e.")]},{slug:"futur-simple",level:"A2",title:"Le futur simple",title_hi:"सामान्य भविष्य काल",summary:"Infinitive + -ai, -as, -a, -ons, -ez, -ont. Used for plans, promises and predictions.",summary_hi:"infinitive + -ai, -as, -a, -ons, -ez, -ont। योजना, वादे और भविष्यवाणी के लिए।",rules:[T("Regular: infinitive (drop final -e of -re) + endings.","नियमित: infinitive + अंत।",L("Je parlerai demain.","I will speak tomorrow.","मैं कल बोलूँगा।"),L("Nous prendrons le train.","We will take the train.","हम ट्रेन लेंगे।")),T("Irregular stems: \xeatre→ser-, avoir→aur-, aller→ir-, faire→fer-, pouvoir→pourr-, venir→viendr-, voir→verr-.","अनियमित धातु (stem) याद करें।",L("Il sera l\xe0 \xe0 huit heures.","He will be there at 8.","वह आठ बजे वहाँ होगा।")),T("After quand/d\xe8s que/lorsque, French uses the future where Hindi/English use the present.","quand/d\xe8s que के बाद फ़्रेंच में भविष्य काल आता है।",L("Quand j’aurai le temps, je viendrai.","When I have time, I’ll come.","जब मेरे पास समय होगा, मैं आऊँगा।"))],tips:["Futur proche (aller + inf.) is more spoken; futur simple more written/formal."],tips_hi:["बोलचाल में aller + infinitive; लिखित/औपचारिक में futur simple।"],quiz:[F("Demain, nous ___ \xe0 Lyon.",["irons","allons","aillons"],0,"aller → ir-: nous irons."),F("Quand il ___ , on partira.",["arrivera","arrive","arriverait"],0,"after quand → futur.")]},{slug:"depuis-pendant",level:"A2",title:"Time expressions: depuis, pendant, il y a, dans, en",title_hi:"समय के शब्द: depuis, pendant, il y a, dans, en",summary:"Choose the right word for duration, origin and future delay.",summary_hi:"अवधि, शुरुआत और भविष्य की देरी के लिए सही शब्द चुनें।",rules:[T("depuis + present = since / for (still going on).","depuis + वर्तमान = से (अब भी जारी)।",L("J’apprends le fran\xe7ais depuis un an.","I have been learning French for a year.","मैं एक साल से फ़्रेंच सीख रहा हूँ।")),T("pendant = for (a finished period). il y a = ago. dans = in (future).","pendant = (पूरी हो चुकी) अवधि; il y a = पहले; dans = अब से इतने बाद।",L("J’ai v\xe9cu \xe0 Paris pendant deux ans.","I lived in Paris for two years.","मैं दो साल पेरिस में रहा।"),L("Il est arriv\xe9 il y a une heure.","He arrived an hour ago.","वह एक घंटे पहले आया।"),L("Le cours commence dans dix minutes.","Class starts in ten minutes.","क्लास दस मिनट बाद शुरू होगी।"))],tips:["Never use the pass\xe9 compos\xe9 with depuis for an action still ongoing."],tips_hi:["जो काम अब भी जारी है, उसमें depuis के साथ pr\xe9sent लगाएँ।"],quiz:[F("Je travaille ici ___ 2020.",["depuis","pendant","il y a"],0,"since a starting point → depuis."),F("Il est parti ___ trois jours.",["depuis","il y a","dans"],1,"ago → il y a.")]},{slug:"adverbes-quantite",level:"A2",title:"Adverbs and quantity",title_hi:"क्रिया-विशेषण और मात्रा",summary:"-ment adverbs and expressions: beaucoup de, un peu de, assez de, trop de.",summary_hi:"-ment वाले क्रिया-विशेषण और मात्रा के शब्द: beaucoup de, un peu de, trop de।",rules:[T("Adverb from adjective: feminine form + -ment (lent → lentement). -ant/-ent → -amment/-emment.","विशेषण के स्त्रीलिंग रूप + -ment।",L("Il parle lentement.","He speaks slowly.","वह धीरे बोलता है।"),L("Elle court rapidement.","She runs quickly.","वह तेज़ दौड़ती है।")),T("Quantity + de + noun (no article).","मात्रा + de + संज्ञा (बिना article)।",L("Il y a beaucoup de monde.","There are a lot of people.","बहुत भीड़ है।"),L("Je mange peu de viande.","I eat little meat.","मैं कम मांस खाता हूँ।"))],tips:["After a negative, du/de la/des → de: Je n’ai pas de temps."],tips_hi:["निषेध के बाद du/des की जगह de: Je n’ai pas de temps।"],quiz:[F("Je n’ai pas ___ argent.",["de","d’","du"],1,"negative + vowel → d’argent."),F("Adverbe de ‘doux’ :",["doucement","douxment","douc\xe9ment"],0,"doux → douce → doucement.")]},{slug:"negation-avancee",level:"A2",title:"More negation: jamais, rien, personne, plus",title_hi:"और निषेध: jamais, rien, personne, plus",summary:"ne … jamais / rien / personne / plus / que / aucun.",summary_hi:"ne … jamais (कभी नहीं), ne … rien (कुछ नहीं), ne … personne (कोई नहीं), ne … plus (अब नहीं), ne … que (सिर्फ़)।",rules:[T("ne goes before the verb; the second word after (before the participle for 'personne').","ne क्रिया से पहले; दूसरा शब्द क्रिया के बाद।",L("Je ne mange jamais de viande.","I never eat meat.","मैं कभी मांस नहीं खाता।"),L("Il n’y a plus de pain.","There is no more bread.","अब रोटी नहीं बची।"),L("Je n’ai vu personne.","I saw nobody.","मैंने किसी को नहीं देखा।")),T("ne … que means 'only' (not a real negative).","ne … que = सिर्फ़ (असल में निषेध नहीं)।",L("Il ne boit que de l’eau.","He drinks only water.","वह सिर्फ़ पानी पीता है।"))],tips:["In speech 'ne' disappears: J’sais pas. In writing and exams, keep ne."],tips_hi:["बोलचाल में ne गायब हो जाता है, पर लिखित परीक्षा में ne ज़रूर लिखें।"],quiz:[F("Je ___ comprends rien.",["ne","pas","plus"],0,"ne … rien."),F("Il n’y a ___ de lait.",["plus","jamais","que"],0,"ne … plus de = no more.")]}],M=[{slug:"passe-compose-imparfait",level:"B1",title:"Pass\xe9 compos\xe9 vs imparfait",title_hi:"pass\xe9 compos\xe9 बनाम imparfait",summary:"Pass\xe9 compos\xe9 = events (what happened). Imparfait = background, habits, descriptions.",summary_hi:"pass\xe9 compos\xe9 = घटना (क्या हुआ); imparfait = पृष्ठभूमि, आदत, वर्णन (कैसा था)।",rules:[T("Imparfait sets the scene; pass\xe9 compos\xe9 interrupts it.","imparfait दृश्य बनाता है; pass\xe9 compos\xe9 उसे बीच में तोड़ता है।",L("Il pleuvait quand je suis sorti.","It was raining when I went out.","जब मैं बाहर निकला तब बारिश हो रही थी।"),L("Je dormais quand le t\xe9l\xe9phone a sonn\xe9.","I was sleeping when the phone rang.","जब फ़ोन बजा तब मैं सो रहा था।")),T("Habits in the past = imparfait; one precise moment = pass\xe9 compos\xe9.","पुरानी आदत = imparfait; एक खास क्षण = pass\xe9 compos\xe9।",L("Enfant, j’allais chez ma grand-m\xe8re chaque \xe9t\xe9.","As a child I went to my grandmother’s every summer.","बचपन में मैं हर गर्मी दादी के घर जाता था।"),L("Hier, je suis all\xe9 chez elle.","Yesterday I went to her place.","कल मैं उसके घर गया।"))],tips:["Clues for imparfait: souvent, toujours, d’habitude, chaque jour. Clues for pass\xe9 compos\xe9: soudain, tout \xe0 coup, hier, une fois.","Feelings and weather in the past are usually imparfait."],tips_hi:["imparfait के संकेत: souvent, d’habitude। pass\xe9 compos\xe9 के संकेत: soudain, hier।"],quiz:[F("Quand j’___ petit, je jouais dehors.",["\xe9tais","ai \xe9t\xe9","serai"],0,"description of childhood → imparfait."),F("Soudain, la porte ___ .",["s’ouvrait","s’est ouverte","s’ouvre"],1,"sudden event → pass\xe9 compos\xe9.")]},{slug:"conditionnel-present",level:"B1",title:"Le conditionnel pr\xe9sent",title_hi:"सशर्त काल (conditionnel)",summary:"Futur stem + imparfait endings. Politeness, advice, wishes, hypotheses.",summary_hi:"भविष्य का stem + imparfait के अंत (-ais, -ais, -ait, -ions, -iez, -aient)। शिष्टता, सलाह, इच्छा।",rules:[T("Politeness and requests.","शिष्ट निवेदन।",L("Pourriez-vous m’aider ?","Could you help me?","क्या आप मेरी मदद कर सकेंगे?"),L("Je voudrais un caf\xe9.","I would like a coffee.","मैं एक कॉफ़ी लेना चाहूँगा।")),T("Advice: devoir / pouvoir in the conditional.","सलाह: devoir/pouvoir का conditionnel।",L("Tu devrais dormir plus.","You should sleep more.","तुम्हें ज़्यादा सोना चाहिए।")),T("Reported/uncertain news (journalism).","अपुष्ट खबर (पत्रकारिता)।",L("Le ministre serait en voyage.","The minister is reportedly travelling.","कहा जा रहा है कि मंत्री यात्रा पर हैं।"))],tables:[S("aimer",["Pronoun","Form"],["je","aimerais"],["tu","aimerais"],["il","aimerait"],["nous","aimerions"],["vous","aimeriez"],["ils","aimeraient"])],tips:["Never use the conditional after 'si' in the same clause: Si j’avais le temps, je viendrais."],tips_hi:["'si' के बाद conditionnel नहीं आता: si + imparfait, conditionnel।"],quiz:[F("Tu ___ voir un m\xe9decin.",["devrais","devras","dois"],0,"advice → conditionnel."),F("Je ___ bien un th\xe9.",["prendrai","prendrais","prends"],1,"polite wish.")]},{slug:"relatifs-simples",level:"B1",title:"Relative pronouns: qui, que, o\xf9, dont",title_hi:"संबंधवाचक: qui, que, o\xf9, dont",summary:"Join two sentences. qui = subject, que = object, o\xf9 = place/time, dont = 'de' + noun.",summary_hi:"दो वाक्य जोड़ना। qui = कर्ता, que = कर्म, o\xf9 = जगह/समय, dont = de + संज्ञा।",rules:[T("qui replaces the subject; que replaces the object.","qui = कर्ता की जगह; que = कर्म की जगह।",L("L’homme qui parle est mon prof.","The man who is speaking is my teacher.","जो आदमी बोल रहा है वह मेरा शिक्षक है।"),L("Le livre que je lis est long.","The book that I’m reading is long.","जो किताब मैं पढ़ रहा हूँ वह लंबी है।")),T("o\xf9 = where/when. dont = whose / about which / of which.","o\xf9 = जहाँ/जब। dont = जिसका / जिसके बारे में।",L("La ville o\xf9 j’habite est calme.","The city where I live is quiet.","जिस शहर में मैं रहता हूँ वह शांत है।"),L("Le film dont tu parles est g\xe9nial.","The film you’re talking about is great.","जिस फ़िल्म की तुम बात कर रहे हो वह शानदार है।"))],tips:["After 'que', the subject comes next: le livre que TU lis.","Verbs with 'de' (parler de, avoir besoin de) → dont."],tips_hi:["जिस क्रिया के साथ 'de' आता है (parler de, avoir besoin de) वहाँ dont लगाएँ।"],quiz:[F("C’est le film ___ j’ai vu hier.",["qui","que","dont"],1,"direct object → que."),F("La fille ___ je parle est nouvelle.",["que","dont","qui"],1,"parler de → dont.")]},{slug:"hypotheses-si",level:"B1",title:"Hypotheses with si",title_hi:"'अगर' वाले वाक्य (si)",summary:"Three patterns: real (present→future), unlikely (imparfait→conditionnel), impossible past (plus-que-parfait→conditionnel pass\xe9).",summary_hi:"तीन ढाँचे: संभव, असंभावित, और बीते कल की असंभव शर्त।",rules:[T("Real: si + pr\xe9sent → futur / pr\xe9sent / imp\xe9ratif.","संभव: si + वर्तमान → भविष्य।",L("Si tu viens, on sortira.","If you come, we’ll go out.","अगर तुम आए तो हम बाहर जाएँगे।")),T("Unlikely/imaginary: si + imparfait → conditionnel pr\xe9sent.","असंभावित: si + imparfait → conditionnel।",L("Si j’avais un million, je voyagerais.","If I had a million I’d travel.","अगर मेरे पास दस लाख होते तो मैं घूमता।")),T("Regret: si + plus-que-parfait → conditionnel pass\xe9.","पछतावा: si + plus-que-parfait → conditionnel pass\xe9।",L("Si j’avais su, je serais venu.","If I had known I would have come.","अगर मुझे पता होता तो मैं आता।"))],tips:["si + il → s’il, but si + elle stays 'si elle'.","No future or conditional right after si."],tips_hi:["si के ठीक बाद futur या conditionnel नहीं लगता।"],quiz:[F("Si j’___ le temps, je t’aiderais.",["avais","aurai","aurais"],0,"si + imparfait."),F("Si tu \xe9tudies, tu ___ ton examen.",["r\xe9ussirais","r\xe9ussiras","as r\xe9ussi"],1,"real condition → futur.")]},{slug:"plus-que-parfait",level:"B1",title:"Plus-que-parfait and past sequence",title_hi:"plus-que-parfait: बीते हुए से भी पहले",summary:"Imparfait of avoir/\xeatre + past participle: an action before another past action.",summary_hi:"avoir/\xeatre का imparfait + participe pass\xe9: किसी बीती घटना से भी पहले हुआ काम।",rules:[T("Use it for the earlier action.","जो काम पहले हुआ था उसके लिए।",L("Quand je suis arriv\xe9, le train \xe9tait d\xe9j\xe0 parti.","When I arrived, the train had already left.","जब मैं पहुँचा, ट्रेन पहले ही जा चुकी थी।"),L("Elle m’a dit qu’elle avait fini.","She told me she had finished.","उसने बताया कि वह खत्म कर चुकी थी।"))],tips:["Same \xeatre/avoir choice and agreements as the pass\xe9 compos\xe9."],tips_hi:["avoir/\xeatre का चुनाव और मेल pass\xe9 compos\xe9 जैसा ही है।"],quiz:[F("Il ___ d\xe9j\xe0 mang\xe9 quand je suis venu.",["avait","a","aurait"],0,"avait mang\xe9."),F("Elles ___ parties avant nous.",["\xe9taient","avaient","sont"],0,"partir uses \xeatre.")]},{slug:"gerondif-participe",level:"B1",title:"G\xe9rondif and present participle",title_hi:"g\xe9rondif (en + -ant)",summary:"en + -ant = while doing / by doing. Same subject for both actions.",summary_hi:"en + -ant = करते हुए / करके। दोनों क्रियाओं का कर्ता एक ही होता है।",rules:[T("Formation: nous-form minus -ons + -ant (parlons → en parlant).","nous रूप से -ons हटाकर -ant।",L("Il lit en mangeant.","He reads while eating.","वह खाते हुए पढ़ता है।"),L("On apprend en pratiquant.","We learn by practising.","अभ्यास करके सीखा जाता है।")),T("Irregular: \xeatre → \xe9tant, avoir → ayant, savoir → sachant.","अनियमित: \xeatre → \xe9tant, avoir → ayant, savoir → sachant।",L("En \xe9tant patient, tu r\xe9ussiras.","By being patient you’ll succeed.","धैर्य रखने से तुम सफल होगे।"))],tips:["Great for writing tasks: replaces 'parce que' and 'quand' and makes sentences shorter."],tips_hi:["लिखित परीक्षा में वाक्य छोटे और सुंदर बनाने में मदद करता है।"],quiz:[F("Il marche ___ t\xe9l\xe9phonant.",["en","\xe0","par"],0,"en + -ant."),F("G\xe9rondif de ‘finir’ :",["en finissant","en finant","en finir"],0,"nous finissons → finissant.")]},{slug:"passif-voix",level:"B1",title:"The passive voice",title_hi:"कर्मवाच्य (passif)",summary:"\xeatre + past participle (agrees with subject) + par. Often avoided with 'on'.",summary_hi:"\xeatre + participe pass\xe9 (कर्ता से मेल) + par। अक्सर 'on' से बदला जाता है।",rules:[T("Tense of \xeatre keeps the tense of the sentence.","\xeatre उसी काल में रहता है जिसमें वाक्य है।",L("Le livre est \xe9crit par Camus.","The book is written by Camus.","किताब कामू द्वारा लिखी गई है।"),L("La maison a \xe9t\xe9 vendue.","The house was sold.","घर बेच दिया गया।")),T("Alternative: on + active verb, or a reflexive.","विकल्प: on + सक्रिय क्रिया या आत्मवाचक।",L("Ici, on parle fran\xe7ais.","French is spoken here.","यहाँ फ़्रेंच बोली जाती है।"),L("\xc7a ne se dit pas.","That isn’t said.","यह नहीं कहा जाता।"))],tips:["Participle agrees: Les lettres sont \xe9crites."],tips_hi:["participle कर्ता से मेल खाता है: Les lettres sont \xe9crites।"],quiz:[F("Les portes ___ ferm\xe9es \xe0 18h.",["sont","ont","est"],0,"passive: \xeatre."),F("Ce roman a \xe9t\xe9 ___ par Hugo.",["\xe9crit","\xe9crire","\xe9crivant"],0,"past participle.")]},{slug:"discours-indirect",level:"B1",title:"Reported speech",title_hi:"अप्रत्यक्ष कथन (discours indirect)",summary:"Report what someone said: change pronouns, time words and (in the past) the tense.",summary_hi:"किसी की बात दोहराना: सर्वनाम, समय-शब्द और अतीत में काल बदलते हैं।",rules:[T("Present report: tense stays the same.","वर्तमान रिपोर्ट: काल नहीं बदलता।",L("Il dit : \xab Je suis fatigu\xe9. \xbb → Il dit qu’il est fatigu\xe9.","He says he is tired.","वह कहता है कि वह थका है।")),T("Past report: pr\xe9sent → imparfait, pass\xe9 compos\xe9 → plus-que-parfait, futur → conditionnel.","अतीत में रिपोर्ट: काल एक कदम पीछे।",L("Elle a dit qu’elle viendrait.","She said she would come.","उसने कहा कि वह आएगी।"),L("Il a demand\xe9 si j’avais mang\xe9.","He asked if I had eaten.","उसने पूछा कि क्या मैंने खाया था।"))],tables:[S("Time words",["Direct","Reported"],["aujourd’hui","ce jour-l\xe0"],["demain","le lendemain"],["hier","la veille"],["maintenant","\xe0 ce moment-l\xe0"],["ici","l\xe0"])],tips:["Questions: est-ce que / inversion disappear → si (yes/no) or the question word."],tips_hi:["हाँ/ना वाले प्रश्न → si; बाकी में प्रश्न-शब्द वही रहता है।"],quiz:[F("\xab Je partirai demain. \xbb → Il a dit qu’il ___ le lendemain.",["partirait","partira","est parti"],0,"futur → conditionnel."),F("\xab Tu as faim ? \xbb → Il m’a demand\xe9 ___ j’avais faim.",["que","si","o\xf9"],1,"yes/no question → si.")]},{slug:"connecteurs-logiques",level:"B1",title:"Logical connectors: cause, consequence, opposition",title_hi:"तर्क-जोड़ने वाले शब्द: कारण, परिणाम, विरोध",summary:"The words that make your speech and writing sound organised — essential for TEF/TCF.",summary_hi:"ये शब्द आपकी बोली और लिखावट को व्यवस्थित बनाते हैं — TEF/TCF में बहुत ज़रूरी।",rules:[T("Cause: parce que, car, puisque, comme, gr\xe2ce \xe0 (positive), \xe0 cause de (negative).","कारण।",L("Je suis en retard \xe0 cause du trafic.","I’m late because of traffic.","मैं ट्रैफ़िक की वजह से लेट हूँ।"),L("J’ai r\xe9ussi gr\xe2ce \xe0 toi.","I passed thanks to you.","मैं तुम्हारी वजह से सफल हुआ।")),T("Consequence: donc, alors, c’est pourquoi, par cons\xe9quent.","परिणाम।",L("Il pleut, donc je reste \xe0 la maison.","It’s raining, so I’m staying home.","बारिश हो रही है, इसलिए मैं घर पर हूँ।")),T("Opposition: mais, pourtant, cependant, en revanche, alors que.","विरोध।",L("Il est riche, pourtant il est triste.","He’s rich, yet he’s sad.","वह अमीर है, फिर भी उदास है।"),L("Lui aime la ville, alors qu’elle pr\xe9f\xe8re la campagne.","He likes the city whereas she prefers the countryside.","उसे शहर पसंद है, जबकि उसे गाँव।"))],tips:["Aim to use 2-3 different connectors in every writing paragraph and spoken answer."],tips_hi:["हर अनुच्छेद और बोले गए जवाब में 2-3 अलग connectors इस्तेमाल करने का लक्ष्य रखें।"],quiz:[F("Il a r\xe9ussi ___ son travail.",["gr\xe2ce \xe0","\xe0 cause de","alors que"],0,"positive cause."),F("Il est petit, ___ il joue tr\xe8s bien au basket.",["pourtant","donc","car"],0,"opposition.")]},{slug:"pronoms-toniques-doubles",level:"B1",title:"Stressed pronouns and pronoun order",title_hi:"बलाघात सर्वनाम (moi, toi…) और क्रम",summary:"moi, toi, lui, elle, nous, vous, eux, elles — used for emphasis and after prepositions.",summary_hi:"moi, toi, lui… — ज़ोर देने और preposition के बाद।",rules:[T("After a preposition, c’est, and for emphasis.","preposition के बाद, c’est के बाद, और ज़ोर के लिए।",L("Je viens avec toi.","I’m coming with you.","मैं तुम्हारे साथ आ रहा हूँ।"),L("Moi, je pr\xe9f\xe8re le th\xe9.","Me, I prefer tea.","मैं तो चाय पसंद करता हूँ।")),T("Two pronouns: me/te/nous/vous BEFORE le/la/les; le/la/les BEFORE lui/leur.","दो सर्वनाम: क्रम याद रखें।",L("Il me le donne.","He gives it to me.","वह मुझे वह देता है।"),L("Je le lui ai dit.","I told it to him.","मैंने उसे यह बताया।"))],tips:["Imperative: Donne-le-moi (le before moi). Negative: Ne me le donne pas."],tips_hi:["आदेश में: Donne-le-moi; निषेध में: Ne me le donne pas।"],quiz:[F("C’est ___ qui ai gagn\xe9.",["je","moi","me"],1,"c’est moi qui…"),F("Il ___ donne le livre. (\xe0 moi)",["me le","le me","moi le"],0,"me before le.")]},{slug:"accord-participe",level:"B1",title:"Agreement of the past participle",title_hi:"participe pass\xe9 का मेल",summary:"With \xeatre: agrees with the subject. With avoir: agrees with a COD placed BEFORE the verb.",summary_hi:"\xeatre के साथ कर्ता से; avoir के साथ तब जब COD क्रिया से पहले हो।",rules:[T("\xeatre → agree with the subject.","\xeatre → कर्ता से मेल।",L("Elles sont arriv\xe9es.","They (f) arrived.","वे (स्त्रियाँ) पहुँचीं।")),T("avoir → agree only if the COD comes before.","avoir → सिर्फ़ तब जब COD पहले हो।",L("La lettre que j’ai \xe9crite.","The letter I wrote.","वह चिट्ठी जो मैंने लिखी।"),L("J’ai \xe9crit la lettre.","I wrote the letter. (no agreement)","मैंने चिट्ठी लिखी। (मेल नहीं)"))],tips:["Reflexive verbs: usually agree with the reflexive pronoun (elle s’est lav\xe9e) unless a COD follows (elle s’est lav\xe9 les mains)."],tips_hi:["आत्मवाचक: आम तौर पर मेल; पर अगर बाद में COD हो (les mains) तो मेल नहीं।"],quiz:[F("Les photos que j’ai ___ .",["pris","prise","prises"],2,"COD 'les photos' placed before."),F("Nous sommes ___ (f).",["all\xe9","all\xe9es","all\xe9s"],1,"nous = women → all\xe9es.")]}],B=[{slug:"subjonctif-usages",level:"B2",title:"Subjunctive: when to use it",title_hi:"subjonctif कब लगाएँ",summary:"After wishes, emotions, doubt, necessity and certain conjunctions (bien que, pour que, avant que, \xe0 condition que).",summary_hi:"इच्छा, भावना, संदेह, ज़रूरत और कुछ conjunctions (bien que, pour que, avant que) के बाद।",rules:[T("Need, wish, order: il faut que, vouloir que, exiger que.","ज़रूरत/इच्छा/आदेश।",L("Il faut que tu viennes.","You must come.","तुम्हें आना ही होगा।"),L("Je veux que vous soyez \xe0 l’heure.","I want you to be on time.","मैं चाहता हूँ कि आप समय पर हों।")),T("Emotion and doubt: \xeatre content que, regretter que, douter que.","भावना और संदेह।",L("Je regrette qu’il soit parti.","I’m sorry he left.","मुझे अफ़सोस है कि वह चला गया।"),L("Je doute qu’elle r\xe9ussisse.","I doubt she’ll succeed.","मुझे शक है कि वह सफल होगी।")),T("Conjunctions: pour que, afin que, bien que, quoique, avant que, \xe0 moins que, jusqu’\xe0 ce que.","ये conjunctions हमेशा subjonctif लेते हैं।",L("Bien qu’il soit fatigu\xe9, il travaille.","Although tired, he works.","थका होने के बावजूद वह काम करता है।"))],tables:[S("Irregular subjonctif",["Verb","que je…","que nous…"],["\xeatre","sois","soyons"],["avoir","aie","ayons"],["aller","aille","allions"],["faire","fasse","fassions"],["pouvoir","puisse","puissions"],["savoir","sache","sachions"])],tips:["Same subject in both clauses → use the infinitive: Je veux partir (not que je parte).","apr\xe8s que (fact) takes the indicative; avant que takes the subjunctive."],tips_hi:["दोनों हिस्सों का कर्ता एक हो तो infinitive: Je veux partir।","apr\xe8s que + indicatif; avant que + subjonctif।"],quiz:[F("Bien qu’il ___ riche, il est avare.",["est","soit","sera"],1,"bien que → subjonctif."),F("Je pense qu’il ___ raison.",["ait","a","aurait"],1,"penser (affirmative) → indicatif.")]},{slug:"relatifs-composes",level:"B2",title:"Compound relatives: lequel, auquel, duquel",title_hi:"संयुक्त संबंधवाचक: lequel, auquel, duquel",summary:"Used after prepositions when the antecedent is a thing: avec lequel, pour laquelle, auquel.",summary_hi:"preposition के बाद वस्तु के लिए: avec lequel, pour laquelle, auquel।",rules:[T("preposition + lequel/laquelle/lesquels/lesquelles (agree with the noun).","preposition + lequel… (संज्ञा से मेल)।",L("Le stylo avec lequel j’\xe9cris.","The pen I write with.","जिस कलम से मैं लिखता हूँ।"),L("La raison pour laquelle je suis venu.","The reason why I came.","वह कारण जिसकी वजह से मैं आया।")),T("\xe0 → auquel / \xe0 laquelle / auxquels; de → duquel / de laquelle / desquels. For people, qui is possible.","\xe0 और de के साथ रूप बदलते हैं।",L("Le projet auquel je pense.","The project I’m thinking of.","जिस प्रोजेक्ट के बारे में मैं सोच रहा हूँ।"),L("L’ami avec qui je voyage.","The friend I travel with.","जिस दोस्त के साथ मैं यात्रा करता हूँ।"))],tips:["'dont' is simpler where possible; use duquel only with a preposition of place (\xe0 c\xf4t\xe9 duquel)."],tips_hi:["जहाँ हो सके dont लगाएँ; duquel सिर्फ़ जगह वाले prepositions (\xe0 c\xf4t\xe9 de) के साथ।"],quiz:[F("La table sur ___ j’ai pos\xe9 le livre.",["laquelle","lequel","laquel"],0,"table is feminine."),F("Le probl\xe8me ___ je r\xe9fl\xe9chis.",["auquel","dont","que"],0,"r\xe9fl\xe9chir \xe0 → auquel.")]},{slug:"futur-anterieur-cond-passe",level:"B2",title:"Futur ant\xe9rieur and conditionnel pass\xe9",title_hi:"futur ant\xe9rieur और conditionnel pass\xe9",summary:"Compound tenses: an action finished before a future moment, or a regret/missed possibility.",summary_hi:"भविष्य के किसी क्षण से पहले पूरा हो चुका काम; या पछतावा/छूटा हुआ अवसर।",rules:[T("futur ant\xe9rieur = future of avoir/\xeatre + participle.","futur ant\xe9rieur = avoir/\xeatre का futur + participe pass\xe9।",L("Quand tu arriveras, j’aurai fini.","By the time you arrive, I’ll have finished.","जब तुम आओगे तब मैं खत्म कर चुका हूँगा।"),L("D\xe8s qu’il sera parti, nous mangerons.","As soon as he has left we’ll eat.","जैसे ही वह जाएगा हम खाएँगे।")),T("conditionnel pass\xe9 = conditionnel of avoir/\xeatre + participle.","conditionnel pass\xe9 = avoir/\xeatre का conditionnel + participe।",L("J’aurais aim\xe9 venir.","I would have liked to come.","मैं आना चाहता, पर…"),L("Tu aurais d\xfb me pr\xe9venir.","You should have warned me.","तुम्हें मुझे बताना चाहिए था।"))],tips:["Great for opinion essays: \xab \xc0 mon avis, on aurait d\xfb agir plus t\xf4t \xbb."],tips_hi:["राय वाले निबंध में बहुत काम आता है।"],quiz:[F("D\xe8s qu’elle ___ , je partirai.",["aura mang\xe9","mangera","mange"],0,"action completed first → futur ant\xe9rieur."),F("Il ___ pu m’aider.",["aurait","avait","a"],0,"il aurait pu.")]},{slug:"doubles-pronoms-mise-en-relief",level:"B2",title:"Emphasis: c’est … qui / que, ce qui / ce que",title_hi:"ज़ोर देना: c’est … qui/que, ce qui/ce que",summary:"Highlight the important idea and talk about unnamed things.",summary_hi:"ज़रूरी बात पर ज़ोर और अनाम चीज़ों के बारे में बात करना।",rules:[T("c’est + element + qui (subject) / que (other).","c’est + तत्व + qui/que।",L("C’est Marie qui a gagn\xe9.","It’s Marie who won.","मैरी ही जीती है।"),L("C’est demain que je pars.","It’s tomorrow that I leave.","मैं कल ही जा रहा हूँ।")),T("ce qui (subject) / ce que (object) / ce dont (de) / ce \xe0 quoi (\xe0) = what.","ce qui/ce que = जो (बात)।",L("Ce qui m’int\xe9resse, c’est la musique.","What interests me is music.","जो मुझे दिलचस्प लगता है वह संगीत है।"),L("Je ne comprends pas ce que tu dis.","I don’t understand what you’re saying.","तुम जो कह रहे हो वह मुझे समझ नहीं आया।"))],tips:["Perfect for speaking Task 3 (opinion): \xab Ce qui me semble essentiel, c’est… \xbb"],tips_hi:["बोलने की परीक्षा में राय देने के लिए बेहतरीन: \xab Ce qui me semble essentiel, c’est… \xbb"],quiz:[F("___ me pla\xeet, c’est la libert\xe9.",["Ce qui","Ce que","Ce dont"],0,"subject → ce qui."),F("Dis-moi ___ tu veux.",["ce qui","ce que","ce dont"],1,"object → ce que.")]},{slug:"expression-concession-opposition",level:"B2",title:"Concession, cause and consequence (advanced)",title_hi:"रियायत, कारण, परिणाम (उन्नत)",summary:"Nuanced linking: malgr\xe9, m\xeame si, quoique, tellement … que, si bien que, d’autant que.",summary_hi:"बारीक जोड़: malgr\xe9, m\xeame si, tellement… que, d’autant que।",rules:[T("Concession: malgr\xe9 + noun, bien que + subj., m\xeame si + indicative.","रियायत: malgr\xe9 + संज्ञा, bien que + subjonctif, m\xeame si + indicatif।",L("Malgr\xe9 la pluie, nous sommes sortis.","Despite the rain we went out.","बारिश के बावजूद हम निकले।"),L("M\xeame s’il pleut, je viendrai.","Even if it rains I’ll come.","बारिश भी हुई तो मैं आऊँगा।")),T("Consequence: si/tellement … que, si bien que, de sorte que.","परिणाम: इतना … कि।",L("Il a tellement travaill\xe9 qu’il est \xe9puis\xe9.","He worked so much that he’s exhausted.","उसने इतना काम किया कि वह थक गया।")),T("Added cause: d’autant plus que, \xe9tant donn\xe9 que, sous pr\xe9texte que.","अतिरिक्त कारण।",L("Il est content, d’autant plus qu’il a r\xe9ussi.","He’s happy, all the more as he succeeded.","वह खुश है, खासकर इसलिए कि वह सफल हुआ।"))],tips:["Use at least one concession in every opinion essay: it shows B2+ control."],tips_hi:["हर निबंध में कम से कम एक concession डालें — इससे B2+ स्तर दिखता है।"],quiz:[F("___ le froid, il est sorti en t-shirt.",["Malgr\xe9","Bien que","Parce que"],0,"followed by a noun → malgr\xe9."),F("Bien que tu ___ raison, je refuse.",["as","aies","auras"],1,"bien que → subjonctif.")]},{slug:"participe-present-adjectif",level:"B2",title:"Present participle and verbal adjective",title_hi:"participe pr\xe9sent और verbal adjective",summary:"-ant forms: participe pr\xe9sent (invariable, replaces qui + verb) vs adjectif verbal (agrees).",summary_hi:"-ant रूप: participe pr\xe9sent (नहीं बदलता) बनाम adjectif verbal (लिंग/वचन से बदलता है)।",rules:[T("Participe pr\xe9sent: invariable, written style, replaces 'qui + verb' or cause.","participe pr\xe9sent: अपरिवर्तनीय, लिखित शैली।",L("Les \xe9l\xe8ves travaillant dur r\xe9ussissent.","Students who work hard succeed.","मेहनत करने वाले छात्र सफल होते हैं।"),L("Ayant fini, il est parti.","Having finished, he left.","खत्म करके वह चला गया।")),T("Adjectif verbal: agrees like an adjective.","adjectif verbal: विशेषण की तरह मेल।",L("Des histoires fascinantes.","Fascinating stories.","रोचक कहानियाँ।"))],tips:["Spelling traps: fatigant (adj.) vs fatiguant (participle); diff\xe9rent vs diff\xe9rant."],tips_hi:["वर्तनी का जाल: fatigant (विशेषण) बनाम fatiguant (क्रिया)।"],quiz:[F("Une femme ___ (charmer).",["charmant","charmante","charmantes"],1,"adjective agrees: charmante."),F("___ peur, il a couru.",["Ayant","Ayante","En ayant"],0,"participe pr\xe9sent, written cause.")]},{slug:"nominalisation-style-ecrit",level:"B2",title:"Nominalisation and formal writing",title_hi:"भाववाचक रूप और औपचारिक लेखन",summary:"Turn verbs into nouns to sound formal: d\xe9cider → la d\xe9cision.",summary_hi:"औपचारिक लेखन के लिए क्रिया को संज्ञा बनाना: d\xe9cider → la d\xe9cision।",rules:[T("Replace subordinate clauses with a noun phrase.","उपवाक्य की जगह संज्ञा-पदबंध।",L("Quand il est arriv\xe9… → \xc0 son arriv\xe9e…","On his arrival…","उसके आने पर…"),L("Parce que le prix augmente → En raison de la hausse des prix","Due to the rise in prices","कीमतें बढ़ने के कारण"))],tables:[S("Useful pairs",["Verb","Noun","Hindi"],["augmenter","l’augmentation","बढ़ोतरी"],["diminuer","la diminution","कमी"],["d\xe9velopper","le d\xe9veloppement","विकास"],["am\xe9liorer","l’am\xe9lioration","सुधार"],["\xe9chouer","l’\xe9chec","असफलता"],["r\xe9ussir","la r\xe9ussite","सफलता"])],tips:["Formal letters (TEF writing B): use 'En raison de', 'Suite \xe0', 'Afin de'."],tips_hi:["औपचारिक पत्र में 'En raison de', 'Suite \xe0', 'Afin de' लिखें।"],quiz:[F("‘augmenter’ → ",["l’augmentation","l’augmente","l’augmentement"],0,"-ation noun."),F("Nominal form of ‘\xe9chouer’ :",["l’\xe9chec","l’\xe9chouement","l’\xe9chouer"],0,"l’\xe9chec.")]},{slug:"inversion-style-soutenu",level:"C1",title:"Stylistic inversion and elevated register",title_hi:"शैलीगत उलटफेर और उच्च भाषा-स्तर",summary:"Inversion after adverbs (peut-\xeatre, sans doute, \xe0 peine, aussi) and in subordinates, found in editorials and DALF.",summary_hi:"समाचार-संपादकीय और DALF में मिलने वाला उलटफेर।",rules:[T("Inversion after \xe0 peine, peut-\xeatre que / peut-\xeatre + inversion, sans doute, aussi (= therefore).","इन क्रिया-विशेषणों के बाद क्रिया-कर्ता उलटते हैं।",L("\xc0 peine \xe9tait-il arriv\xe9 qu’il est reparti.","Hardly had he arrived when he left.","वह मुश्किल से पहुँचा ही था कि फिर चला गया।"),L("Peut-\xeatre a-t-il oubli\xe9.","Maybe he forgot.","शायद वह भूल गया।")),T("Fixed formulas: Ainsi, Toujours est-il que…, Reste \xe0 savoir si…","स्थिर वाक्यांश।",L("Toujours est-il que le projet a \xe9chou\xe9.","The fact remains that the project failed.","सच यही है कि प्रोजेक्ट विफल रहा।"))],tips:["Use sparingly: one or two stylish inversions per essay lifts the score to C1."],tips_hi:["कम इस्तेमाल करें — एक-दो सुंदर inversion निबंध को C1 बना देते हैं।"],quiz:[F("Peut-\xeatre ___ -il raison.",["a","a-t","as"],1,"inversion with t: a-t-il."),F("\xc0 peine ___ -elle sortie…",["est","\xe9tait","a"],1,"\xe0 peine + plus-que-parfait (inversion).")]},{slug:"passe-simple-litteraire",level:"C1",title:"Pass\xe9 simple and literary tenses",title_hi:"pass\xe9 simple (साहित्यिक भूतकाल)",summary:"The narrative past of novels and news essays. Learn to recognise it; use mainly 3rd person.",summary_hi:"उपन्यासों का भूतकाल। पहचानना ज़रूरी, लिखना कम।",rules:[T("Endings: -a/-\xe8rent for -er verbs; -it/-irent for -ir/-re; -ut/-urent for -oir/-ire irregulars.","3rd person रूप सबसे ज़्यादा मिलते हैं।",L("Il ouvrit la porte et entra.","He opened the door and entered.","उसने दरवाज़ा खोला और अंदर गया।"),L("Ils partirent \xe0 l’aube.","They left at dawn.","वे भोर में निकले।"))],tables:[S("Common irregulars (il / ils)",["Infinitive","il","ils"],["\xeatre","fut","furent"],["avoir","eut","eurent"],["faire","fit","firent"],["venir","vint","vinrent"],["voir","vit","virent"],["dire","dit","dirent"])],tips:["Imparfait (description) + pass\xe9 simple (event) in a story, like imparfait + pass\xe9 compos\xe9 in speech."],tips_hi:["कहानी में imparfait वर्णन के लिए और pass\xe9 simple घटना के लिए।"],quiz:[F("Il ___ la lettre. (lire)",["lit","lut","lisait"],1,"lire → il lut."),F("Ils ___ au village. (aller)",["all\xe8rent","allaient","iront"],0,"ils all\xe8rent.")]},{slug:"argumentation-c1",level:"C1",title:"Argumentation toolbox",title_hi:"तर्क करने का टूलबॉक्स",summary:"Structure a persuasive text or talk: thesis, arguments, counter-arguments, conclusion.",summary_hi:"प्रभावी निबंध/भाषण की संरचना: थीसिस, तर्क, प्रतितर्क, निष्कर्ष।",rules:[T("Introduce a thesis and give your position.","थीसिस और अपनी राय।",L("Il est ind\xe9niable que… Pour ma part, je soutiens que…","It is undeniable that… For my part, I maintain that…","यह निर्विवाद है कि… मैं तो मानता हूँ कि…")),T("Add, contrast, concede.","जोड़ना, विरोध करना, मानना।",L("En outre / De surcro\xeet / Certes… mais… / Il n’en reste pas moins que…","Moreover / Admittedly… but…","इसके अलावा / माना कि… लेकिन…")),T("Conclude.","निष्कर्ष।",L("En d\xe9finitive, force est de constater que…","Ultimately, one has to admit that…","अंततः मानना पड़ेगा कि…"))],tips:["Plan: Introduction (accroche + probl\xe9matique) → 2-3 arguments with examples → conclusion + ouverture."],tips_hi:["योजना: भूमिका → 2-3 तर्क + उदाहरण → निष्कर्ष।"],quiz:[F("‘En outre’ means:",["moreover","however","therefore"],0,"adds an argument."),F("‘Il n’en reste pas moins que’ introduces:",["a conclusion despite objections","a question","a cause"],0,"'nevertheless the fact is'.")]}],z={"etre-avoir":{title:"\xeatre और avoir (होना, रखना)",summary:"फ्रेंच की दो सबसे ज़रूरी क्रियाएँ। ये अनियमित हैं और बीते काल में सहायक क्रिया भी बनती हैं। उम्र बताने में avoir: J’ai 20 ans।"},"articles-gender":{title:"Articles और लिंग",summary:"हर संज्ञा पुल्लिंग या स्त्रीलिंग होती है और article उसे बताता है: le/la/les = the, un/une/des = a/some।"},"present-er-verbs":{title:"-er क्रियाओं का वर्तमान काल",summary:"लगभग 90% क्रियाएँ -er पर खत्म होती हैं। -er हटाइए और -e, -es, -e, -ons, -ez, -ent जोड़िए।"},"negation-questions":{title:"निषेध और प्रश्न",summary:"क्रिया को ne … pas से घेरिए: Je ne parle pas। प्रश्न: est-ce que, आवाज़ ऊँची करके, या inversion।"},"irregular-aller-faire":{title:"aller और faire",summary:"aller (जाना) और faire (करना/बनाना) — बेहद आम अनियमित क्रियाएँ; इनसे futur proche भी बनता है।"},"passe-compose":{title:"pass\xe9 compos\xe9 (बीता काल)",summary:"avoir/\xeatre + participe pass\xe9। बीती हुई पूरी घटना बताने के लिए। गतिवाचक क्रियाएँ और आत्मवाचक क्रियाएँ \xeatre लेती हैं।"},"futur-proche-pronouns":{title:"futur proche और सर्वनाम",summary:"aller + infinitive = जल्द होने वाला काम। साथ ही सर्वनाम का स्थान।"},imparfait:{title:"imparfait (अधूरा/आदत वाला भूतकाल)",summary:"बीते समय का वर्णन, आदतें और पृष्ठभूमि: Quand j’\xe9tais petit, je jouais dehors।"},"futur-conditionnel":{title:"futur और conditionnel",summary:"भविष्य (-rai) और सशर्त/शिष्ट रूप (-rais)।"},"subjonctif-present":{title:"subjonctif pr\xe9sent",summary:"ज़रूरत, इच्छा, भावना के बाद: Il faut que tu viennes।"},"pronoms-relatifs":{title:"संबंधवाचक सर्वनाम",summary:"qui, que, dont, o\xf9, lequel जैसे शब्दों से वाक्य जोड़ना।"},"plus-que-parfait-hypotheses":{title:"plus-que-parfait और शर्तें",summary:"बीते हुए से भी पहले का काम, और अतीत की असंभव शर्तें।"},"concordance-passe-simple":{title:"काल-मेल और pass\xe9 simple",summary:"लिखित/साहित्यिक भाषा में कालों का तालमेल।"},"registre-soutenu":{title:"उच्च भाषा-स्तर (registre soutenu)",summary:"औपचारिक और साहित्यिक भाषा के शब्द और रचनाएँ।"}},O={CO:{fr:"Compr\xe9hension orale",en:"Listening",hi:"सुनना"},CE:{fr:"Compr\xe9hension \xe9crite",en:"Reading",hi:"पढ़ना"},EO:{fr:"Expression orale",en:"Speaking",hi:"बोलना"},EE:{fr:"Expression \xe9crite",en:"Writing",hi:"लिखना"}},J=[{id:"tef-canada",name:"TEF Canada",tagline:"The most common test for Canadian immigration (Express Entry) and citizenship.",tagline_hi:"कनाडा इमिग्रेशन (Express Entry) और नागरिकता के लिए सबसे आम परीक्षा।",levels:"A1 → C2 (results mapped to NCLC 1-12)",usedFor:["Express Entry","Quebec immigration","Citizenship"],parts:[{skill:"CO",duration:"≈ 40 min",detail:"60 questions, audio played once. Short dialogues, announcements, interviews. Difficulty rises as you go.",detail_hi:"60 सवाल, ऑडियो सिर्फ़ एक बार चलता है। सवाल धीरे-धीरे कठिन होते जाते हैं।"},{skill:"CE",duration:"≈ 60 min",detail:"50 questions: ads, notices, articles. Reading speed matters: ~1 minute per question.",detail_hi:"50 सवाल: विज्ञापन, सूचनाएँ, लेख। गति ज़रूरी है: लगभग 1 मिनट प्रति सवाल।"},{skill:"EE",duration:"60 min",detail:"Section A: continue a news item (min. 80 words). Section B: formal letter giving an opinion (min. 200 words).",detail_hi:"भाग A: किसी समाचार को आगे बढ़ाएँ (कम से कम 80 शब्द)। भाग B: राय देने वाला औपचारिक पत्र (कम से कम 200 शब्द)।"},{skill:"EO",duration:"15 min",detail:"Section A: ask questions about an ad to get information (≈ 5 min). Section B: convince a friend / argue a point (≈ 10 min).",detail_hi:"भाग A: विज्ञापन के बारे में सवाल पूछें। भाग B: दोस्त को मनाएँ / अपनी बात तर्क से रखें।"}],scoring:"Each skill scored out of 360 (CO), 300 (CE), 450 (EO and EE). Each score maps to its own NCLC level.",tips:["In listening, read the options BEFORE the audio and write numbers quickly.","Writing B: use a formal opening and closing (Madame, Monsieur … Veuillez agr\xe9er…).","Speaking A: prepare 8-10 question openers: Pouvez-vous me dire… ? Est-ce qu’il est possible de… ?"],tips_hi:["सुनने में ऑडियो से पहले विकल्प पढ़ें और संख्याएँ जल्दी लिखें।","औपचारिक पत्र में शुरुआत और अंत के नियम पक्के करें।","बोलने में सवाल पूछने के 8-10 वाक्य रट लें।"]},{id:"tcf-canada",name:"TCF Canada",tagline:"Another IRCC-accepted test with multiple-choice listening and reading.",tagline_hi:"IRCC द्वारा मान्य दूसरी परीक्षा; सुनना और पढ़ना बहुविकल्पीय होता है।",levels:"A1 → C2 (results mapped to NCLC)",usedFor:["Express Entry","Citizenship","University"],parts:[{skill:"CO",duration:"35 min",detail:"39 questions, audio played once, difficulty rises (A1 to C2).",detail_hi:"39 सवाल, ऑडियो एक बार, कठिनाई बढ़ती जाती है।"},{skill:"CE",duration:"60 min",detail:"39 questions on texts of increasing difficulty.",detail_hi:"39 सवाल, पाठ क्रमशः कठिन।"},{skill:"EE",duration:"60 min",detail:"3 tasks: short message (60-120 words), article/blog (120-150 words), argumentative text with two viewpoints (120-180 words).",detail_hi:"3 कार्य: छोटा संदेश, लेख/ब्लॉग, दो पक्षों वाला तर्क-पाठ।"},{skill:"EO",duration:"≈ 12 min",detail:"3 tasks: guided interview (no preparation), role-play (2 min preparation), express and defend an opinion.",detail_hi:"3 कार्य: साक्षात्कार, रोल-प्ले, अपनी राय का बचाव।"}],scoring:"Listening and reading scored out of 699; writing and speaking scored out of 20. Each maps to NCLC.",tips:["Wrong answers are not penalised: always answer every question.","Time yourself: 90 seconds per reading question maximum.","Writing: respect the word limit of each task."],tips_hi:["गलत जवाब पर नंबर नहीं कटते — हर सवाल का जवाब दें।","समय का हिसाब रखें।","हर कार्य की शब्द-सीमा का पालन करें।"]},{id:"delf-dalf",name:"DELF / DALF",tagline:"Lifelong diplomas from the French Ministry of Education, one per CEFR level.",tagline_hi:"फ़्रांस के शिक्षा मंत्रालय के आजीवन वैध डिप्लोमा, हर CEFR स्तर के लिए अलग।",levels:"DELF A1, A2, B1, B2 \xb7 DALF C1, C2",usedFor:["Study in France","Visa / residence","Career"],parts:[{skill:"CO",duration:"20-40 min",detail:"Listen to 2-3 recordings and answer questions (heard twice at A1-B2).",detail_hi:"2-3 रिकॉर्डिंग सुनकर जवाब दें।"},{skill:"CE",duration:"30-60 min",detail:"Read documents and answer comprehension questions.",detail_hi:"पाठ पढ़कर सवालों के जवाब।"},{skill:"EE",duration:"45-90 min",detail:"Write letters, essays or an argued synthesis according to the level.",detail_hi:"स्तर के अनुसार पत्र, निबंध या संश्लेषण।"},{skill:"EO",duration:"6-30 min",detail:"Guided talk, monologue and exchange with the examiner.",detail_hi:"परीक्षक के साथ बातचीत और एकालाप।"}],scoring:"Each skill out of 25; total out of 100. Pass = 50/100 with at least 5/25 in every skill.",tips:["B2 (DELF) is roughly NCLC 7-8: the best target for most visa and study goals.","DELF diplomas never expire."],tips_hi:["DELF B2 लगभग NCLC 7-8 के बराबर है।","DELF डिप्लोमा कभी एक्सपायर नहीं होता।"]}],D=[{nclc:4,cefr:"A2",tefCO:"145-180",tefCE:"121-150",tefEE:"181-225",tefEO:"181-225",tcfCO:"331-368",tcfCE:"342-374",tcfEE:"4-5",tcfEO:"4-5",note:"Basic survival French.",note_hi:"बुनियादी ज़रूरत भर की फ़्रेंच।"},{nclc:5,cefr:"B1",tefCO:"181-216",tefCE:"151-180",tefEE:"226-270",tefEO:"226-270",tcfCO:"369-397",tcfCE:"375-405",tcfEE:"6",tcfEO:"6",note:"Handles everyday topics.",note_hi:"रोज़मर्रा के विषय संभाल लेता है।"},{nclc:6,cefr:"B1+",tefCO:"217-248",tefCE:"181-206",tefEE:"271-309",tefEO:"271-309",tcfCO:"398-457",tcfCE:"406-452",tcfEE:"7-9",tcfEO:"7-9",note:"Independent user; many Quebec streams start here.",note_hi:"स्वतंत्र उपयोगकर्ता; कई क्यूबेक स्ट्रीम यहीं से शुरू।"},{nclc:7,cefr:"B2",tefCO:"249-279",tefCE:"207-232",tefEE:"310-348",tefEO:"310-348",tcfCO:"458-502",tcfCE:"453-498",tcfEE:"10-11",tcfEO:"10-11",note:"Key Express Entry French threshold (bonus points).",note_hi:"Express Entry का मुख्य फ़्रेंच लक्ष्य (बोनस अंक)।"},{nclc:8,cefr:"B2+",tefCO:"280-297",tefCE:"233-247",tefEE:"349-373",tefEO:"349-373",tcfCO:"503-522",tcfCE:"499-523",tcfEE:"12-13",tcfEO:"12-13",note:"Strong professional French.",note_hi:"मज़बूत पेशेवर फ़्रेंच।"},{nclc:9,cefr:"C1",tefCO:"298-315",tefCE:"248-262",tefEE:"374-397",tefEO:"374-397",tcfCO:"523-548",tcfCE:"524-548",tcfEE:"14-15",tcfEO:"14-15",note:"Advanced user.",note_hi:"उन्नत उपयोगकर्ता।"},{nclc:10,cefr:"C1+",tefCO:"316-360",tefCE:"263-300",tefEE:"398-450",tefEO:"398-450",tcfCO:"549-699",tcfCE:"549-699",tcfEE:"16-20",tcfEO:"16-20",note:"Maximum points for French.",note_hi:"फ़्रेंच के अधिकतम अंक।"}],H=[{stage:1,level:"A1",nclc:"NCLC 1-3",title:"Survive and introduce yourself",title_hi:"शुरुआत: परिचय और ज़रूरी बातें",hours:"60-80 h",goals:["Greet, introduce yourself, numbers, time","\xeatre/avoir, -er verbs, articles","300-500 core words"],goals_hi:["अभिवादन, परिचय, संख्याएँ, समय","\xeatre/avoir, -er क्रियाएँ, articles","300-500 मूल शब्द"],doNow:["Do grammar topics A1","Flashcards: 10 words/day","Listen to slow audio daily"]},{stage:2,level:"A2",nclc:"NCLC 4",title:"Daily life and the past",title_hi:"रोज़मर्रा की ज़िंदगी और अतीत",hours:"80-100 h",goals:["Pass\xe9 compos\xe9, futur proche, pronouns","Shop, travel, describe routine","800-1,200 words"],goals_hi:["pass\xe9 compos\xe9, सर्वनाम","ख़रीदारी, यात्रा, दिनचर्या","800-1200 शब्द"],doNow:["Grammar A2 + quizzes","Translate drill A2","Practise TEF speaking Section A questions"]},{stage:3,level:"B1",nclc:"NCLC 5-6",title:"Independent speaker",title_hi:"स्वतंत्र वक्ता",hours:"120-150 h",goals:["Imparfait vs pass\xe9 compos\xe9, conditionnel, si-clauses","Express opinions with connectors","2,000+ words"],goals_hi:["imparfait, conditionnel, si-वाक्य","connectors से राय देना","2000+ शब्द"],doNow:["Grammar B1 topics","Write a 120-word message every day","First timed practice test"]},{stage:4,level:"B2",nclc:"NCLC 7-8",title:"Target for Express Entry",title_hi:"लक्ष्य: Express Entry (NCLC 7+)",hours:"150-200 h",goals:["Subjonctif, relatifs compos\xe9s, concession","Write 200-word formal letters","Understand news and interviews at normal speed","3,500+ words"],goals_hi:["subjonctif, relatifs compos\xe9s","200 शब्द का औपचारिक पत्र","सामान्य गति की ख़बरें समझना","3500+ शब्द"],doNow:["Full TEF/TCF mock tests every week","Shadow podcasts / RFI / TV5Monde","Record yourself on speaking Task 3"]},{stage:5,level:"C1",nclc:"NCLC 9-10",title:"Advanced mastery beyond NCLC 7",title_hi:"NCLC 7 से आगे: उन्नत महारत",hours:"200+ h",goals:["Nuanced argumentation, register control","Stylistic inversion, pass\xe9 simple recognition","Read Le Monde, Radio-Canada, literature","5,000+ words"],goals_hi:["तर्क की बारीकियाँ, भाषा-स्तर पर पकड़","साहित्य और अख़बार पढ़ना","5000+ शब्द"],doNow:["C1 grammar + argumentation toolbox","Weekly opinion essays with feedback","Debate a topic aloud for 5 minutes"]}],R=[{id:"ce-a2-affiche",skill:"CE",level:"A2",nclc:"NCLC 4",title:"Affiche : cours de cuisine",title_en:"Poster: cooking class",fr:"Cours de cuisine fran\xe7aise\nTous les samedis, de 10 h \xe0 12 h, au centre culturel de la rue Victor-Hugo. Prix : 25 € par personne. Apportez un tablier. Inscription obligatoire avant le jeudi.",en:"French cooking class. Every Saturday, 10 am to 12 pm, at the cultural centre on Victor-Hugo Street. Price: €25 per person. Bring an apron. Registration required before Thursday.",hi:"फ़्रेंच खाना पकाने की क्लास। हर शनिवार सुबह 10 से 12 बजे, विक्टर-ह्यूगो गली के सांस्कृतिक केंद्र में। कीमत: 25 € प्रति व्यक्ति। एप्रन लाएँ। गुरुवार से पहले पंजीकरण ज़रूरी।",questions:[F("Quand a lieu le cours ?",["Le jeudi matin","Le samedi matin","Le samedi soir"],1,"Tous les samedis, 10 h-12 h."),F("Qu’est-ce qu’on doit apporter ?",["Un tablier","Des l\xe9gumes","Un livre"],0,"Apportez un tablier."),F("Avant quand faut-il s’inscrire ?",["Avant samedi","Avant jeudi","Avant lundi"],1,"Inscription avant le jeudi.")]},{id:"ce-b1-article",skill:"CE",level:"B1",nclc:"NCLC 5-6",title:"Article : le t\xe9l\xe9travail",title_en:"Article: remote work",fr:"Depuis la pand\xe9mie, le t\xe9l\xe9travail s’est install\xe9 dans de nombreuses entreprises. Les salari\xe9s appr\xe9cient de gagner du temps sur les trajets et de mieux organiser leur journ\xe9e. Pourtant, certains se plaignent de l’isolement et de la difficult\xe9 \xe0 s\xe9parer vie priv\xe9e et vie professionnelle. Beaucoup d’employeurs choisissent donc un syst\xe8me hybride : deux ou trois jours \xe0 la maison, le reste au bureau.",en:"Since the pandemic, remote work has become established in many companies. Employees appreciate saving commute time and organising their day better. However, some complain about isolation and difficulty separating private and professional life. Many employers therefore choose a hybrid system: two or three days at home, the rest at the office.",hi:"महामारी के बाद कई कंपनियों में घर से काम आम हो गया। कर्मचारियों को यात्रा का समय बचना पसंद है, पर कुछ अकेलेपन की शिकायत करते हैं। इसलिए कई नियोक्ता हाइब्रिड व्यवस्था चुनते हैं: 2-3 दिन घर, बाकी दफ़्तर।",questions:[F("Quel est un avantage du t\xe9l\xe9travail ?",["Gagner du temps","Gagner plus d’argent","Voir ses coll\xe8gues"],0,"Gagner du temps sur les trajets."),F("Quel probl\xe8me est mentionn\xe9 ?",["Le bruit","L’isolement","Le salaire"],1,"L’isolement."),F("Que choisissent beaucoup d’employeurs ?",["Un syst\xe8me hybride","Le bureau uniquement","Le t\xe9l\xe9travail total"],0,"Un syst\xe8me hybride.")]},{id:"ce-b2-opinion",skill:"CE",level:"B2",nclc:"NCLC 7",title:"Opinion : r\xe9duire la voiture en ville",title_en:"Opinion: reducing cars in cities",fr:"Interdire les voitures au centre-ville ne r\xe9soudra pas, \xe0 lui seul, le probl\xe8me de la pollution. Certes, l’air y serait plus pur, mais encore faut-il que les transports en commun soient assez fr\xe9quents et abordables. Faute de quoi, les habitants des banlieues, qui n’ont souvent pas d’alternative, se sentiraient p\xe9nalis\xe9s. Il importe donc d’accompagner toute mesure restrictive d’un investissement massif dans les bus, le m\xe9tro et les pistes cyclables.",en:"Banning cars from the city centre will not, on its own, solve pollution. Admittedly the air would be cleaner, but public transport must be frequent and affordable. Otherwise suburban residents, who often have no alternative, would feel penalised. Any restrictive measure should therefore come with massive investment in buses, metro and bike lanes.",hi:"शहर के केंद्र में गाड़ियों पर रोक लगाना अकेले प्रदूषण का हल नहीं है। हवा तो साफ़ होगी, पर सार्वजनिक परिवहन बार-बार चलने वाला और सस्ता होना चाहिए, वरना उपनगर वाले खुद को दंडित महसूस करेंगे। इसलिए हर पाबंदी के साथ बस, मेट्रो और साइकिल लेन में बड़ा निवेश चाहिए।",questions:[F("Quelle est la th\xe8se de l’auteur ?",["L’interdiction suffit","L’interdiction ne suffit pas seule","Il faut plus de voitures"],1,"Elle ne r\xe9soudra pas \xe0 elle seule."),F("\xab Faute de quoi \xbb signifie :",["Sinon","Parce que","Ensuite"],0,"Faute de quoi = otherwise."),F("Que demande-t-il ?",["Moins de bus","Plus d’investissement dans les transports","Plus de parkings"],1,"Investissement massif.")]},{id:"ce-c1-editorial",skill:"CE",level:"C1",nclc:"NCLC 9-10",title:"\xc9ditorial : l’intelligence artificielle",title_en:"Editorial: artificial intelligence",fr:"Qu’on s’en r\xe9jouisse ou qu’on le d\xe9plore, l’intelligence artificielle s’invite d\xe9sormais dans la plupart des m\xe9tiers. Si elle promet des gains de productivit\xe9 substantiels, elle suscite aussi des inqui\xe9tudes l\xe9gitimes quant \xe0 la place de l’humain. Reste \xe0 savoir si les pouvoirs publics sauront encadrer ces technologies sans en brider l’essor. Toujours est-il que l’\xe9ducation, plus que jamais, devra pr\xe9parer chacun \xe0 travailler avec ces outils plut\xf4t que contre eux.",en:"Whether we welcome or deplore it, artificial intelligence is now entering most professions. While promising substantial productivity gains, it raises legitimate concerns about the human role. It remains to be seen whether public authorities can regulate without stifling growth. Still, education must now prepare everyone to work with these tools, not against them.",hi:"चाहे स्वागत करें या अफ़सोस, AI अब ज़्यादातर पेशों में आ चुका है। यह उत्पादकता बढ़ाता है पर इंसान की जगह को लेकर चिंता भी पैदा करता है। देखना है कि सरकारें बिना विकास रोके नियमन कर पाती हैं या नहीं। शिक्षा को लोगों को इन औज़ारों के साथ काम करना सिखाना होगा।",questions:[F("Quelle est la position de l’auteur ?",["Rejet total","Nuanc\xe9e : promesses et risques","Enthousiasme sans r\xe9serve"],1,"Il met en balance les gains et les inqui\xe9tudes."),F("\xab Brider l’essor \xbb signifie :",["Freiner le d\xe9veloppement","Acc\xe9l\xe9rer","Financer"],0,"Brider = to restrain."),F("Quel r\xf4le pour l’\xe9ducation ?",["Interdire ces outils","Pr\xe9parer \xe0 travailler avec eux","Ne rien changer"],1,"Travailler avec plut\xf4t que contre.")]},{id:"co-a2-gare",skill:"CO",level:"A2",nclc:"NCLC 4",title:"Annonce en gare",title_en:"Station announcement",fr:"Mesdames et messieurs, le train \xe0 destination de Lyon, pr\xe9vu \xe0 quatorze heures trente, partira avec vingt minutes de retard, voie num\xe9ro douze. Nous vous prions de nous excuser pour ce d\xe9sagr\xe9ment.",en:"Ladies and gentlemen, the train to Lyon, scheduled for 2:30 pm, will leave 20 minutes late from platform 12. We apologise for the inconvenience.",hi:"देवियो और सज्जनो, लियों जाने वाली ट्रेन जो 14:30 पर थी, 20 मिनट देरी से प्लेटफ़ॉर्म 12 से जाएगी। असुविधा के लिए खेद है।",questions:[F("Quelle est la destination ?",["Lyon","Lille","Nice"],0,"Lyon."),F("Quel est le retard ?",["10 minutes","20 minutes","30 minutes"],1,"Vingt minutes."),F("Quelle voie ?",["2","12","20"],1,"Voie douze.")]},{id:"co-b1-message",skill:"CO",level:"B1",nclc:"NCLC 5-6",title:"Message vocal",title_en:"Voicemail",fr:"Bonjour Claire, c’est Marc. Je t’appelle parce que la r\xe9union de demain est report\xe9e \xe0 jeudi, \xe0 dix heures, en salle B. Comme ma voiture est au garage, je viendrai en m\xe9tro. Peux-tu apporter les documents du client ? Merci et \xe0 bient\xf4t !",en:"Hello Claire, it’s Marc. The meeting tomorrow is postponed to Thursday at ten, in room B. As my car is in the garage I’ll come by metro. Can you bring the client documents? Thanks and see you soon!",hi:"हैलो क्लेयर, मैं मार्क हूँ। कल की मीटिंग गुरुवार को दस बजे कमरा B में होगी। मेरी गाड़ी गैराज में है, इसलिए मैं मेट्रो से आऊँगा। क्या तुम क्लाइंट के दस्तावेज़ ला सकती हो?",questions:[F("Quand a lieu la r\xe9union ?",["Demain","Jeudi","Vendredi"],1,"Report\xe9e \xe0 jeudi."),F("Pourquoi Marc vient-il en m\xe9tro ?",["Sa voiture est au garage","Il aime le m\xe9tro","Il n’a pas de voiture"],0,"Sa voiture est au garage."),F("Que doit apporter Claire ?",["Un caf\xe9","Les documents du client","Son ordinateur"],1,"Les documents du client.")]},{id:"co-b2-radio",skill:"CO",level:"B2",nclc:"NCLC 7",title:"Interview radio : le b\xe9n\xe9volat",title_en:"Radio interview: volunteering",fr:"Selon une \xe9tude r\xe9cente, pr\xe8s d’un Fran\xe7ais sur quatre s’engage dans une association. Ce qui motive les b\xe9n\xe9voles, ce n’est pas seulement l’envie d’aider : c’est aussi le d\xe9sir d’apprendre de nouvelles comp\xe9tences et de cr\xe9er des liens. Cependant, de plus en plus d’associations peinent \xe0 recruter des jeunes, qui manquent de temps \xe0 cause de leurs \xe9tudes.",en:"According to a recent study, nearly one French person in four volunteers in an association. Volunteers are motivated not only by the wish to help but also to learn skills and make connections. However, more associations struggle to recruit young people, who lack time because of their studies.",hi:"एक अध्ययन के अनुसार हर चार में से लगभग एक फ़्रेंच व्यक्ति किसी संस्था में स्वयंसेवा करता है। प्रेरणा सिर्फ़ मदद नहीं, कौशल सीखना और संबंध बनाना भी है। पर संस्थाओं को युवा नहीं मिल रहे क्योंकि उनके पास समय कम है।",questions:[F("Quelle proportion de Fran\xe7ais est b\xe9n\xe9vole ?",["1 sur 4","1 sur 10","1 sur 2"],0,"Pr\xe8s d’un sur quatre."),F("Quelle motivation est cit\xe9e ?",["L’argent","Apprendre de nouvelles comp\xe9tences","Voyager"],1,"Comp\xe9tences et liens."),F("Quel est le probl\xe8me pour les associations ?",["Recruter des jeunes","Trouver des salles","Payer les salari\xe9s"],0,"Peinent \xe0 recruter des jeunes.")]}],W=[{id:"ee-a2-message",exam:"TCF",level:"A2",nclc:"NCLC 4",title:"Message \xe0 un ami",minWords:60,prompt:"Vous avez un nouvel appartement. \xc9crivez un message \xe0 un ami pour l’inviter \xe0 une f\xeate samedi. D\xe9crivez l’appartement et dites ce qu’il doit apporter.",prompt_hi:"आपका नया फ़्लैट है। दोस्त को शनिवार की पार्टी का निमंत्रण लिखें, फ़्लैट का वर्णन करें और बताएँ वह क्या लाए।",model:"Salut Paul,\nJ’ai enfin un nouvel appartement ! Il est petit mais lumineux, avec un grand balcon. Pour f\xeater \xe7a, j’organise une f\xeate samedi \xe0 19 h. Peux-tu venir ? Apporte une boisson et ta bonne humeur !\n\xc0 bient\xf4t,\nSara",model_en:"Hi Paul, I finally have a new flat! It is small but bright, with a large balcony. To celebrate I’m having a party Saturday at 7 pm. Can you come? Bring a drink and your good mood! See you soon, Sara",checklist:["Greeting + closing","Invitation (date, time)","Description (2 adjectives)","Instruction with the imperative"]},{id:"ee-b1-reclamation",exam:"TEF",level:"B1",nclc:"NCLC 5-6",title:"Lettre de r\xe9clamation",minWords:120,prompt:"Vous avez achet\xe9 un ordinateur qui ne fonctionne pas. \xc9crivez au service client pour expliquer le probl\xe8me et demander une solution.",prompt_hi:"आपने जो कंप्यूटर खरीदा वह काम नहीं करता। ग्राहक-सेवा को समस्या बताते हुए पत्र लिखें और समाधान माँगें।",model:"Madame, Monsieur,\nJe vous \xe9cris au sujet de l’ordinateur que j’ai achet\xe9 le 3 mars dans votre magasin. D\xe8s la premi\xe8re utilisation, l’\xe9cran s’est \xe9teint plusieurs fois et la batterie ne tient pas plus de vingt minutes. J’ai pourtant suivi toutes les instructions.\nC’est pourquoi je vous demande de bien vouloir remplacer l’appareil ou de me rembourser. Vous trouverez ci-joint la facture.\nDans l’attente de votre r\xe9ponse, je vous prie d’agr\xe9er, Madame, Monsieur, mes salutations distingu\xe9es.\nA. Kumar",model_en:"I am writing regarding the computer I bought on 3 March in your shop. From first use the screen turned off several times and the battery lasts only twenty minutes… I therefore ask you to replace or refund it. Invoice attached. Yours faithfully.",checklist:["Formal opening/closing","Facts: date, problem, what you tried","Clear request (remplacer / rembourser)","Connectors: pourtant, c’est pourquoi"]},{id:"ee-b2-opinion",exam:"TEF",level:"B2",nclc:"NCLC 7",title:"Lettre d’opinion : les r\xe9seaux sociaux",minWords:200,prompt:"Un journal local demande l’avis des lecteurs : les r\xe9seaux sociaux sont-ils bons pour les jeunes ? \xc9crivez une lettre (200 mots minimum) pour donner et justifier votre opinion.",prompt_hi:"स्थानीय अख़बार पूछता है: क्या सोशल मीडिया युवाओं के लिए अच्छा है? कम से कम 200 शब्दों में अपनी राय तर्क सहित लिखें।",model:"Madame, Monsieur,\nEn r\xe9ponse \xe0 votre question, je pense que les r\xe9seaux sociaux pr\xe9sentent autant d’avantages que de risques pour les jeunes.\nD’une part, ils permettent de rester en contact avec ses proches, de s’informer rapidement et m\xeame de d\xe9velopper des comp\xe9tences cr\xe9atives. Par exemple, de nombreux adolescents apprennent les langues gr\xe2ce \xe0 des vid\xe9os.\nD’autre part, un usage excessif peut nuire au sommeil, \xe0 la concentration et \xe0 l’estime de soi, car on a tendance \xe0 se comparer aux autres. Bien que ces plateformes soient gratuites, elles collectent aussi beaucoup de donn\xe9es personnelles.\n\xc0 mon avis, il ne faut ni les interdire ni les laisser sans contr\xf4le. Il est essentiel que les parents et l’\xe9cole apprennent aux jeunes \xe0 les utiliser avec discernement.\nEn conclusion, c’est l’usage, et non l’outil, qui est bon ou mauvais.\nVeuillez agr\xe9er, Madame, Monsieur, mes salutations distingu\xe9es.",model_en:"Argues both sides: benefits (contact, information, skills) and risks (sleep, concentration, self-esteem, data), then concludes that education and supervision are the solution.",checklist:["Thesis in the first paragraph","D’une part… d’autre part…","At least one concession (bien que + subjonctif)","Example + conclusion","200+ words"]},{id:"ee-c1-argument",exam:"DELF",level:"C1",nclc:"NCLC 9-10",title:"Essai argumentatif : le t\xe9l\xe9travail g\xe9n\xe9ralis\xe9",minWords:250,prompt:"\xab Le t\xe9l\xe9travail devrait devenir la norme pour tous les emplois qui le permettent. \xbb Discutez cette affirmation dans un essai structur\xe9 (250 mots).",prompt_hi:"\xab जिन नौकरियों में संभव है, उनके लिए घर से काम ही नियम बने। \xbb इस कथन पर संरचित निबंध लिखें।",model:"Il est ind\xe9niable que le t\xe9l\xe9travail a boulevers\xe9 nos habitudes. Reste \xe0 savoir s’il doit devenir la norme.\nCertes, il offre une autonomie accrue et r\xe9duit l’empreinte \xe9cologique des d\xe9placements. En outre, il \xe9largit le recrutement \xe0 des candidats \xe9loign\xe9s des grands centres.\nIl n’en reste pas moins que l’\xe9loignement fragilise la coh\xe9sion d’\xe9quipe et la transmission des savoir-faire, surtout pour les jeunes recrues. De surcro\xeet, tous les foyers ne disposent pas d’un espace de travail ad\xe9quat.\n\xc0 mon sens, la solution r\xe9side dans un mod\xe8le hybride, n\xe9goci\xe9 au cas par cas. En d\xe9finitive, force est de constater que la flexibilit\xe9 vaut mieux que la norme unique.",model_en:"Thesis → concession → counter-argument → personal position (hybrid) → conclusion. Uses C1 linkers: il est ind\xe9niable que, certes, il n’en reste pas moins que, force est de constater.",checklist:["Probl\xe9matique","Plan en 3 parties","Linkers C1","Nuanced personal position","Conclusion with opening"]}],V=[{id:"eo-a2-interview",exam:"TCF",level:"A2",nclc:"NCLC 4",title:"Entretien dirig\xe9",minutes:2,prompt:"Pr\xe9sentez-vous : nom, \xe2ge, pays, travail ou \xe9tudes, famille, loisirs, et pourquoi vous apprenez le fran\xe7ais.",prompt_hi:"अपना परिचय दें: नाम, उम्र, देश, काम/पढ़ाई, परिवार, शौक, और फ़्रेंच क्यों सीख रहे हैं।",phrases:[{fr:"Je m’appelle… et j’ai… ans.",hi:"मेरा नाम… है और मैं… साल का हूँ।"},{fr:"J’apprends le fran\xe7ais parce que je veux vivre au Canada.",hi:"मैं फ़्रेंच इसलिए सीख रहा हूँ कि कनाडा में रहना चाहता हूँ।"},{fr:"Pendant mon temps libre, j’aime…",hi:"खाली समय में मुझे… पसंद है।"}]},{id:"eo-b1-infos",exam:"TEF",level:"B1",nclc:"NCLC 5-6",title:"Section A : demander des informations",minutes:5,prompt:"Vous lisez une annonce pour un cours de natation. T\xe9l\xe9phonez pour obtenir un maximum d’informations (prix, horaires, niveau, inscription).",prompt_hi:"आप तैराकी क्लास का विज्ञापन पढ़ते हैं। फ़ोन करके अधिकतम जानकारी लें (कीमत, समय, स्तर, पंजीकरण)।",phrases:[{fr:"Bonjour, je vous appelle au sujet de votre annonce.",hi:"नमस्ते, मैं आपके विज्ञापन के बारे में फ़ोन कर रहा हूँ।"},{fr:"Pourriez-vous me dire combien co\xfbte le cours ?",hi:"क्या आप बता सकते हैं कि क्लास की कीमत कितनी है?"},{fr:"Est-ce qu’il y a des cours pour d\xe9butants ?",hi:"क्या शुरुआती लोगों के लिए क्लास है?"},{fr:"Comment est-ce que je peux m’inscrire ?",hi:"मैं पंजीकरण कैसे कर सकता हूँ?"}]},{id:"eo-b2-convaincre",exam:"TEF",level:"B2",nclc:"NCLC 7",title:"Section B : convaincre un ami",minutes:10,prompt:"Un ami h\xe9site \xe0 quitter son emploi pour \xe9tudier. Vous le convainquez de ne pas le faire (ou de le faire). Donnez au moins trois arguments et r\xe9pondez \xe0 ses objections.",prompt_hi:"आपका दोस्त नौकरी छोड़कर पढ़ने की सोच रहा है। उसे मनाएँ (या रोकें): कम से कम तीन तर्क दें और उसके एतराज़ों का जवाब दें।",phrases:[{fr:"\xc0 ta place, je r\xe9fl\xe9chirais bien avant de d\xe9cider.",hi:"तुम्हारी जगह होता तो फ़ैसले से पहले अच्छे से सोचता।"},{fr:"Je comprends ton point de vue, mais il faut aussi consid\xe9rer que…",hi:"मैं तुम्हारी बात समझता हूँ, पर यह भी सोचो कि…"},{fr:"D’abord… ensuite… enfin…",hi:"पहले… फिर… अंत में…"},{fr:"Imagine que tu aies un dipl\xf4me : tu gagnerais bien plus.",hi:"सोचो तुम्हारे पास डिग्री हो: तुम कहीं ज़्यादा कमाओगे।"}]},{id:"eo-c1-debat",exam:"DELF",level:"C1",nclc:"NCLC 9-10",title:"Expos\xe9 et d\xe9bat",minutes:10,prompt:"Pr\xe9sentez en 3 minutes votre position sur : \xab Faut-il limiter l’usage des smartphones \xe0 l’\xe9cole ? \xbb puis r\xe9pondez au contradicteur.",prompt_hi:"3 मिनट में अपनी राय रखें: \xab क्या स्कूल में स्मार्टफ़ोन सीमित हों? \xbb फिर विरोधी के सवालों के जवाब दें।",phrases:[{fr:"La question qui se pose est de savoir si…",hi:"सवाल यह है कि क्या…"},{fr:"Certes, … ; toutefois, …",hi:"माना कि…; फिर भी…"},{fr:"Force est de reconna\xeetre que…",hi:"यह मानना पड़ेगा कि…"},{fr:"Pour r\xe9sumer, je dirais que…",hi:"सारांश में मैं कहूँगा कि…"}]}],Q=["A1","A2","B1","B2","C1"],G=["A1","A2","B1","B2","C1"],U=[...E.map(e=>{var s,t;return{...e,title_hi:null==(s=z[e.slug])?void 0:s.title,summary_hi:null==(t=z[e.slug])?void 0:t.summary}}),...P,...M,...B].sort((e,s)=>G.indexOf(e.level)-G.indexOf(s.level)),Y=[{id:"poetry",label:"Poetry",blurb:"Songs, fables and verse from Ronsard to Baudelaire, with line-by-line translation."},{id:"literature",label:"Literature",blurb:"Graded stories, then classics by Perrault, Voltaire, Flaubert and Maupassant."},{id:"translate",label:"Translate",blurb:"Build French sentences and decode them back to English, by level."},{id:"grammar",label:"Grammar",blurb:"Simple rules with Hindi meaning, examples, tables and quizzes: from zero to C1."},{id:"exams",label:"Exams",blurb:"TEF Canada, TCF Canada and DELF/DALF: formats, NCLC scores, practice and a roadmap beyond NCLC 7."},{id:"resources",label:"Resources",blurb:"Your books with covers, plus the best free websites, podcasts and tools for learning French."}],K=e=>"poetry"===e?C:"literature"===e?N:[],X=e=>{let s=[...e];for(let e=s.length-1;e>0;e--){let t=Math.floor(Math.random()*(e+1));[s[e],s[t]]=[s[t],s[e]]}return s}